  atlas = {
    continents = { [1414] = "Kalimdor", [1415] = "Eastern Kingdoms" },
    zones = {
      [1411] = { name = "Durotar", continent = 1414, note = { "Durotar's red gullies channel the roads between its settlements. Razor Hill stands at their meeting, with Orgrimmar to the north, Sen'jin Village toward the south coast and the crossing into the Barrens to the west.", "The Valley of Trials lies apart from the main road. Tiragarde Keep occupies the eastern coast, while the Echo Isles are visible offshore from Darkspear country without being safely in Darkspear hands.", "Outside Orgrimmar, the zeppelin towers give the approach a second skyline above the canyon walls. A traveller looking for a sea crossing here should look upward." }, places = { { "Drygulch Ravine", 475, 120, 575, 210, 370 }, { "Echo Isles", 600, 470, 710, 660, 368 }, { "Kolkar Crag", 460, 500, 520, 560, 366 }, { "Razor Hill", 500, 245, 595, 325, 362 }, { "Razormane Grounds", 350, 230, 475, 350, 816 }, { "Sen'jin Village", 525, 450, 600, 525, 367 }, { "Skull Rock", 500, 55, 575, 105, 817 }, { "Thunder Ridge", 355, 105, 460, 220, 369 }, { "Tiragarde Keep", 535, 325, 620, 425, 372 }, { "Valley of Trials", 395, 395, 495, 500, 363 } } },
      [1412] = { name = "Mulgore", continent = 1414, note = { "Green plains and grazing kodo under a big sky: the tauren's home. Thunder Bluff stands on its mesas in the north; Bloodhoof Village sits in the south, and the road runs between them and out east to the Barrens.", "The plains are kind, mostly. The water wells are the tauren's, and worth guarding; the gnolls of Palemane Rock, the harpies of Windfury Ridge and the Venture Company's mine are not. The dwarves at the Bael'dun digsite dig where the tauren would rather they did not.", "Red Rocks, in the east, is a resting place of the tauren's honoured dead. Walk there quietly." }, places = { { "Bael'dun Digsite", 280, 309, 373, 369, 404 }, { "Bloodhoof Village", 434, 388, 507, 445, 222 }, { "Brambleblade Ravine", 546, 495, 684, 584, 358 }, { "Palemane Rock", 311, 424, 373, 491, 818 }, { "Ravaged Caravan", 497, 331, 546, 372, 224 }, { "Red Cloud Mesa", 386, 510, 549, 597, 220 }, { "Red Rocks", 536, 168, 622, 254, 225 }, { "Skywatcher Plateau", 218, 0, 521, 225, 17045, visit = true }, { "The Golden Plains", 457, 203, 534, 329, 820 }, { "The Rolling Plains", 549, 422, 662, 488, 821 }, { "The Venture Co. Mine", 559, 315, 628, 381, 360 }, { "Thunderhorn Water Well", 417, 312, 473, 356, 397 }, { "Wildmane Water Well", 399, 138, 454, 187, 398 }, { "Windfury Ridge", 454, 101, 561, 173, 819 }, { "Winterhoof Water Well", 501, 437, 539, 483, 396 } } },
      [1413] = { name = "The Barrens", continent = 1414, note = { "The Crossroads gives the Barrens a centre from which the roads spread plainly: north toward Ashenvale, east to Ratchet, west into Stonetalon, and south through Camp Taurajo toward the Great Lift.", "The open country makes distant landmarks easy to see and easy to underestimate. Thorn walls mark quilboar ground; centaur camps and scattered oases interrupt the plains. A place visible on the horizon may still take a long walk to reach.", "Ratchet's harbour connects the east coast with Booty Bay. Inland, the road is the most dependable line through a landscape that offers room in every direction." }, places = { { "Agama'gor", 390, 275, 475, 370, 1700 }, { "Bael Modan", 450, 530, 505, 590, 359 }, { "Blackthorn Ridge", 385, 490, 450, 565, 1701 }, { "Boulder Lode Mine", 595, 10, 645, 80, 381 }, { "Bramblescar", 485, 355, 530, 425, 1698 }, { "Camp Taurajo", 425, 380, 490, 435, 378 }, { "Dreadmist Peak", 450, 95, 520, 150, 384 }, { "Far Watch Post", 590, 115, 635, 170, 379 }, { "Field of Giants", 425, 445, 500, 500, 390 }, { "Grol'dom Farm", 530, 105, 585, 150, 1704 }, { "Honor's Stand", 335, 155, 415, 225, 1702 }, { "Lushwater Oasis", 435, 225, 500, 295, 387 }, { "Northwatch Hold", 575, 340, 650, 400, 385 }, { "Raptor Grounds", 530, 320, 590, 365, 1697 }, { "Ratchet", 600, 225, 655, 275, 392 }, { "Razorfen Downs", 445, 580, 535, 645, 1316 }, { "Razorfen Kraul", 370, 555, 450, 625, 1717 }, { "The Crossroads", 485, 165, 550, 215, 380 }, { "The Dry Hills", 350, 60, 445, 135, 383 }, { "The Forgotten Pools", 420, 125, 490, 190, 386 }, { "The Merchant Coast", 615, 270, 660, 335, 391 }, { "The Mor'shan Rampart", 440, 15, 520, 75, 1703 }, { "The Sludge Fen", 505, 20, 605, 80, 382 }, { "The Stagnant Oasis", 530, 255, 585, 315, 388 }, { "Thorn Hill", 540, 165, 600, 215, 1699 } } },
      [1416] = { name = "Alterac Mountains", continent = 1415, note = { "The road out of Hillsbrad climbs from green foothills into snow and the remains of Alterac's kingdom. Strahnbrad is occupied by the Syndicate, while ogres hold much of the ruined capital. A tower on a ridge is a useful landmark, but a poor promise of shelter.", "Dalaran stands beside Lordamere Lake, where Archmage Modera seeks help with a crisis inside the city. Disrupted ley lines have turned its constructs destructive. The city has guards enough to look orderly from the road.", "Higher up, yeti caves and snowfields interrupt the mountain paths. The lake gives a fixed point below; among the ridges, the next turning is often hidden." }, places = { { "Chillwind Point", 730, 330, 915, 560, 1684, 3486 }, { "Corrahn's Dagger", 435, 495, 530, 625, 1679 }, { "Crushridge Hold", 435, 215, 535, 345, 282, 283 }, { "Dandred's Fold", 370, 70, 440, 160, 1682 }, { "Gallows' Corner", 460, 355, 545, 430, 1357 }, { "Gavin's Naze", 270, 525, 345, 620, 1677 }, { "Growless Cave", 345, 420, 450, 505, 1683 }, { "Lordamere Internment Camp", 160, 525, 250, 610, 278 }, { "Misty Shore", 220, 190, 345, 315, 1681 }, { "Ruins of Alterac", 330, 295, 470, 420, 281 }, { "Sofera's Naze", 540, 415, 630, 505, 1678 }, { "Strahnbrad", 570, 255, 700, 350, 280 }, { "The Headland", 345, 545, 435, 660, 1680 }, { "The Uplands", 500, 120, 630, 245, 284 } } },
      [1417] = { name = "Arathi Highlands", continent = 1415, note = { "Thandol Span carries the Wetlands road into a country of green slopes and old fortifications. Thoradin's Wall marks the western passage toward Hillsbrad; Stromgarde's great walls rise above the south-western coast.", "Refuge Pointe lies among the central hills for the Alliance, while Hammerfall holds the north-east for the Horde. Stromgarde itself is divided between surviving defenders, Syndicate forces and ogres. A wall drawn intact on a map need not enclose a single safe settlement.", "The binding circles are conspicuous landmarks on the open ground. Faldir's Cove is tucked below the southern cliffs, much less apparent from the road than from the sea." }, places = { { "Boulder'gor", 350, 215, 405, 340, 1858 }, { "Boulderfist Hall", 475, 425, 610, 560, 316 }, { "Circle of East Binding", 595, 175, 680, 280, 333 }, { "Circle of Inner Binding", 315, 365, 420, 460, 335 }, { "Circle of Outer Binding", 485, 320, 570, 385, 336 }, { "Circle of West Binding", 170, 110, 275, 230, 334 }, { "Dabyrie's Farmstead", 505, 230, 600, 300, 315 }, { "Faldir's Cove", 215, 475, 405, 590, 327 }, { "Go'Shek Farm", 575, 340, 655, 415, 314 }, { "Hammerfall", 690, 190, 815, 300, 321 }, { "Northfold Manor", 275, 150, 360, 270, 313 }, { "Refuge Pointe", 420, 260, 500, 370, 320 }, { "Stromgarde Keep", 140, 340, 315, 490, 324 }, { "Thandol Span", 400, 485, 520, 625, 880 }, { "Thoradin's Wall", 125, 180, 230, 325, 1857 }, { "Witherbark Village", 595, 410, 740, 485, 317 } } },
      [1418] = { name = "Badlands", continent = 1415, note = { "The descent from Loch Modan leaves the green country abruptly behind. Red ridges break the Badlands into long, dry valleys, with Kargath's walls in the west and the excavations around Uldaman near the northern approach.", "Angor Fortress is Dark Iron ground. Ogre camps occupy the southern hills, and black dragonkin hold Lethlor Ravine in the east. The clearest open stretch is not necessarily the quietest route.", "The League's diggings provide several useful landmarks, though a tent and a spoil heap can look much alike from the next ridge. In this country, the colour of the stone tells a surveyor less than its shape." }, places = { { "Agmond's End", 400, 420, 545, 570, 345 }, { "Angor Fortress", 360, 170, 500, 275, 338 }, { "Apocryphan's Rest", 100, 360, 215, 465, 337 }, { "Camp Boff", 545, 400, 685, 570, 342 }, { "Camp Cagg", 40, 475, 225, 615, 344 }, { "Camp Kosh", 600, 100, 725, 200, 341 }, { "Dustwind Gulch", 565, 245, 690, 370, 1898 }, { "Hammertoe's Digsite", 500, 190, 635, 295, 346 }, { "Kargath", 10, 265, 165, 370, 340 }, { "Lethlor Ravine", 685, 225, 885, 455, 339 }, { "Mirage Flats", 215, 420, 400, 585, 1879 }, { "The Dustbowl", 220, 275, 390, 415, 1878 }, { "The Maker's Terrace", 400, 50, 585, 170, 1897 }, { "Valley of Fangs", 400, 320, 530, 440, 1877 } } },
      [1419] = { name = "Blasted Lands", continent = 1415, note = { "The road south from the Swamp of Sorrows reaches Nethergarde Keep above a red waste. The fortress watches the Dark Portal, whose surviving frame stands farther south in the country the invasion scarred.", "Dreadmaul ogres occupy the western hills, and demons hold the Tainted Scar. Beyond the keep, a traveller has few friendly landmarks to work between. The Portal is easy enough to find; finding a comfortable place near it is another matter." }, places = { { "Altar of Storms", 365, 180, 430, 245, 1441 }, { "Dreadmaul Hold", 385, 65, 480, 125, 1437 }, { "Dreadmaul Post", 450, 255, 560, 335, 1439 }, { "Garrison Armory", 520, 65, 600, 120, 1457 }, { "Nethergarde Keep", 595, 85, 695, 160, 1438 }, { "Rise of the Defiler", 445, 160, 530, 240, 2517 }, { "Serpent's Coil", 575, 190, 685, 255, 1440 }, { "The Dark Portal", 520, 325, 650, 430, 72 }, { "The Tainted Scar", 265, 295, 495, 540, 73 } } },
      [1420] = { name = "Tirisfal Glades", continent = 1415, note = { "The roads of Tirisfal connect Deathknell, Brill and the ruins of Lordaeron's capital, then run east toward the Bulwark. The old farms and mills still give the countryside recognisable divisions, though many of their inhabitants are dead.", "The Scarlet Monastery occupies the north-east, with watch posts beyond it. Brightwater Lake has murlocs along its banks, and the woods conceal dangers of their own.", "Brill provides the Forsaken's principal roadside settlement. Near the capital's ruins, zeppelin towers connect this quiet country with Orgrimmar and Grom'gol, an unexpectedly busy meeting of routes above the trees." }, places = { { "Agamand Mills", 384, 183, 522, 303, 157 }, { "Balnir Farmstead", 664, 335, 795, 489, 165 }, { "Brightwater Lake", 633, 165, 735, 398, 162 }, { "Brill", 560, 320, 635, 418, 159 }, { "Cold Hearth Manor", 502, 365, 575, 436, 166 }, { "Crusader Outpost", 708, 292, 853, 395, 167 }, { "Deathknell", 279, 366, 411, 488, 154 }, { "Garren's Haunt", 531, 182, 627, 328, 164 }, { "Nightmare Vale", 401, 396, 547, 490, 811 }, { "Ruins of Lordaeron", 463, 361, 783, 617, 153, visit = true }, { "Scarlet Watch Post", 740, 114, 820, 325, 459 }, { "Solliden Farmstead", 284, 290, 437, 371, 156 }, { "Stillwater Pond", 429, 307, 532, 378, 810 }, { "Terrace of Repose", 746, 125, 1002, 381, 161, 160, visit = true }, { "The Bulwark", 770, 380, 905, 550, 152 }, { "Venomweb Vale", 777, 240, 970, 408, 812 }, { "Whispering Forest", 4, 198, 339, 622, 16616, visit = true } } },
      [1421] = { name = "Silverpine Forest", continent = 1415, note = { "Silverpine stretches between Tirisfal and the closed border of Gilneas. The Sepulcher lies above the main road, which continues south past Pyrewood and turns toward Hillsbrad.", "Shadowfang Keep stands over Pyrewood, whose familiar village streets become worgen ground at night. Farther south, the Greymane Wall blocks the road into Gilneas. It is a boundary with a kingdom behind it, not a pass through the mountains.", "Ambermill's mages occupy the eastern woods. Between their holdings, the keep and the Forsaken settlements, a short crossing on the map passes several very different claims to the forest." }, places = { { "Ambermill", 580, 370, 690, 470, 233 }, { "Beren's Peril", 550, 450, 630, 515, 231 }, { "Deep Elem Mine", 530, 285, 595, 360, 213 }, { "Fenris Isle", 625, 125, 815, 260, 172 }, { "Malden's Orchard", 535, 50, 600, 90, 238 }, { "North Tide's Hollow", 365, 160, 445, 220, 928 }, { "Olsen's Farthing", 430, 330, 510, 390, 229 }, { "Pyrewood Village", 410, 465, 490, 520, 204 }, { "Shadowfang Keep", 390, 410, 495, 475, 236 }, { "The Dead Field", 430, 115, 500, 175, 240 }, { "The Decrepit Ferry", 510, 205, 600, 280, 237 }, { "The Greymane Wall", 420, 530, 510, 620, 230 }, { "The Sepulcher", 405, 240, 490, 305, 228 }, { "The Shining Strand", 510, 115, 575, 190, 927 }, { "The Skittering Dark", 325, 70, 425, 140, 226 } } },
      [1422] = { name = "Western Plaguelands", continent = 1415, note = { "The road enters at the Bulwark and crosses ruined farming country toward the Thondroril River. Andorhal stands near the centre, its roads and broken buildings still marking the old grain town.", "Hearthglen remains a Scarlet stronghold in the north. In the south, Caer Darrow occupies an island in Darrowmere Lake, with Scholomance beneath it; Chillwind Camp gives the Alliance a foothold nearby.", "The farms are easy to identify and difficult to approach. Their plague cauldrons have made each field a separate piece of hostile ground, where a map of roads must serve a purpose very different from bringing the harvest in." }, places = { { "Caer Darrow", 640, 455, 740, 550, 2298 }, { "Dalson's Tears", 420, 315, 510, 390, 200 }, { "Darrowmere Lake", 555, 410, 815, 575, 2297 }, { "Felstone Field", 335, 340, 415, 405, 199 }, { "Gahrron's Withering", 580, 345, 680, 420, 201 }, { "Hearthglen", 365, 55, 580, 185, 190 }, { "Northridge Lumber Camp", 425, 195, 525, 290, 192 }, { "Ruins of Andorhal", 380, 420, 495, 505, 193 }, { "Sorrow Hill", 470, 485, 565, 575, 197 }, { "The Bulwark", 205, 350, 325, 425, 813 }, { "The Weeping Cave", 615, 240, 690, 325, 198 }, { "The Writhing Haunt", 500, 405, 570, 470, 202 }, { "Thondroril River", 625, 120, 730, 395, 2620 } } },
      [1423] = { name = "Eastern Plaguelands", continent = 1415, note = { "The Thondroril River marks the western approach to a country of dead trees and ruined farms. The roads reach Stratholme in the north-west and Light's Hope Chapel in the east, where the Argent Dawn maintains a refuge.", "Tyr's Hand is a Scarlet stronghold in the south-east; Zul'Mashar occupies the northern heights. Above the Plaguewood hangs Naxxramas. Few landmarks are easier to recognise or less welcome to see.", "Darrowshire's buildings still mark a village on the plain, though its inhabitants belong to a more troubled account. In this country a map can remain perfectly accurate after almost everything it describes has been lost." }, places = { { "Blackwood Lake", 475, 290, 565, 375, 2624 }, { "Corin's Crossing", 550, 430, 645, 510, 2264 }, { "Crown Guard Tower", 345, 465, 430, 545, 2263 }, { "Darrowshire", 340, 560, 460, 640, 2262 }, { "Eastwall Tower", 645, 290, 715, 375, 2271 }, { "Lake Mereldar", 565, 490, 690, 580, 2621 }, { "Light's Hope Chapel", 785, 350, 860, 430, 2268 }, { "Northdale", 665, 170, 750, 255, 2272 }, { "Northpass Tower", 515, 145, 645, 235, 2275 }, { "Pestilent Scar", 695, 355, 790, 480, 2622 }, { "Plaguewood", 235, 160, 495, 290, 2277 }, { "Quel'Lithien Lodge", 485, 80, 575, 140, 2276 }, { "Stratholme", 245, 35, 380, 170, 2279 }, { "Terrordale", 115, 180, 240, 250, 2627 }, { "The Fungal Vale", 355, 300, 455, 395, 2258 }, { "The Infectis Scar", 475, 405, 580, 485, 2623 }, { "The Marris Stead", 215, 455, 320, 525, 2260 }, { "The Noxious Glade", 785, 225, 905, 330, 2270 }, { "The Undercroft", 245, 520, 325, 610, 2261 }, { "Thondroril River", 25, 255, 130, 550, 2619 }, { "Tyr's Hand", 765, 505, 935, 605, 2266 }, { "Zul'Mashar", 670, 60, 795, 135, 2273 } } },
      [1424] = { name = "Hillsbrad Foothills", continent = 1415, note = { "Hillsbrad lies between Alterac's slopes and the sea. Southshore gives the Alliance a port and a town on the coast; Tarren Mill is the Forsaken's foothold inland. Farms and contested roads occupy the space between them.", "The eastern route reaches Arathi through Thoradin's Wall. Other ways lead west into Silverpine, north into Alterac and up toward the Hinterlands. Durnholde's ruined walls are conspicuous near the eastern roads, though the Syndicate now holds the old internment keep.", "This ought to be simple country to cross: low hills, worked fields and ample roads. The difficulty is seldom the ground." }, places = { { "Azurelode Mine", 215, 345, 310, 420, 288 }, { "Darrow Hill", 435, 190, 585, 260, 1056 }, { "Dun Garok", 675, 405, 770, 550, 290 }, { "Durnholde Keep", 705, 220, 835, 325, 275 }, { "Eastern Strand", 550, 440, 690, 555, 294 }, { "Hillsbrad Fields", 250, 200, 450, 400, 286 }, { "Nethander Stead", 580, 290, 700, 450, 289 }, { "Purgation Isle", 110, 480, 235, 585, 896 }, { "Southpoint Tower", 75, 245, 235, 370, 285 }, { "Southshore", 445, 310, 550, 430, 271 }, { "Tarren Mill", 545, 100, 680, 245, 272 }, { "Western Strand", 240, 415, 475, 495, 295 } } },
      [1425] = { name = "The Hinterlands", continent = 1415, note = { "The western approach climbs from Hillsbrad to Aerie Peak, where the Wildhammer's gryphons share the heights above the valley. The road then winds east through wooded hills and old troll holdings.", "Jintha'Alor rises in terraces in the south-east, while Seradane's great tree marks dragon-held country to the north. Revantusk Village occupies the eastern coast and offers the Horde its own foothold below the hills.", "Aerie Peak's height gives a fine first view, but much of the route disappears under trees before it reaches the sea. The Wildhammer have chosen an excellent country for travelling by gryphon." }, places = { { "Aerie Peak", 85, 285, 210, 390, 348 }, { "Agol'watha", 440, 205, 555, 290, 1884 }, { "Hiri'watha", 230, 365, 335, 460, 1885 }, { "Jintha'Alor", 550, 360, 700, 570, 354 }, { "Plaguemist Ravine", 190, 180, 265, 330, 1882 }, { "Quel'Danil Lodge", 255, 225, 375, 350, 350 }, { "Seradane", 560, 90, 725, 250, 356 }, { "Shadra'Alor", 295, 430, 400, 525, 353 }, { "Shaol'watha", 635, 285, 770, 390, 1917 }, { "Skulk Rock", 550, 250, 635, 325, 351 }, { "The Altar of Zul", 440, 405, 535, 480, 355 }, { "The Creeping Ruin", 455, 315, 550, 400, 1886 }, { "The Overlook Cliffs", 755, 350, 835, 570, 307 }, { "Valorwind Lake", 365, 355, 440, 425, 1883 } } },
      [1426] = { name = "Dun Morogh", continent = 1415, note = { "Snow, stone and dwarves, in that order. The valleys run east and west below the peaks that hide Ironforge, and the one road follows them: from Coldridge Valley through the tunnel to Kharanos, up to the city's great gate, and on east through the pass to Loch Modan.", "Kharanos has the Thunderbrew distillery and the best fire in the land. West of it the ground belongs to the Frostmane trolls, and further west Gnomeregan stands behind its walls, poisoned; the gnomes do not go home, and you should not go in without good reason and better friends.", "Carry a spare cloak and keep to the road in a snowstorm. The drifts are deep, and the troggs of Coldridge do not care that you are lost." }, places = { { "Amberstill Ranch", 605, 315, 665, 360, 803 }, { "Brewnall Village", 280, 275, 330, 340, 137 }, { "Chill Breeze Valley", 320, 320, 400, 390, 801 }, { "Coldridge Pass", 320, 420, 380, 490, 800 }, { "Coldridge Valley", 190, 445, 340, 560, 132, 77 }, { "Frostmane Hold", 260, 315, 305, 375, 135 }, { "Gates of Ironforge", 397, 163, 717, 419, 809, visit = true }, { "Gnomeregan", 205, 215, 280, 295, 133 }, { "Gol'Bolar Quarry", 640, 340, 735, 430, 134 }, { "Helm's Bed Lake", 730, 315, 810, 410, 212 }, { "Iceflow Lake", 315, 195, 385, 320, 211 }, { "Kharanos", 386, 294, 642, 550, 131 }, { "Misty Pine Refuge", 545, 245, 605, 325, 138 }, { "North Gate Outpost", 800, 205, 860, 300, 808 }, { "Shimmer Ridge", 380, 220, 440, 315, 802 }, { "South Gate Outpost", 825, 305, 885, 375, 806 }, { "The Grizzled Den", 380, 350, 440, 425, 136 }, { "The Tundrid Hills", 555, 355, 645, 410, 804 } } },
      [1427] = { name = "Searing Gorge", continent = 1415, note = { "The Cauldron cuts a great pit into the centre of Searing Gorge, with Dark Iron workings extending below the surface. From above, the scaffolds and mine entrances show only part of the country a traveller may have to cross.", "Thorium Point is the Thorium Brotherhood's foothold in the north. Blackrock Mountain provides the passage south into the Burning Steppes; approaches from the neighbouring lands reach the gorge through narrower breaks in the mountains.", "Slag heaps and broken machinery make useful landmarks here. It is a working landscape, however ruined it looks from the next ridge." }, places = { { "Blackchar Cave", 155, 415, 305, 565, 1957 }, { "Dustfire Valley", 530, 60, 820, 330, 1959 }, { "Firewatch Ridge", 160, 130, 400, 320, 1442 }, { "Grimesilt Dig Site", 560, 345, 740, 440, 247 }, { "Tanner Camp", 605, 440, 785, 580, 1958 }, { "The Cauldron", 315, 260, 610, 400, 246 }, { "The Sea of Cinders", 330, 460, 570, 665, 1444 } } },
      [1428] = { name = "Burning Steppes", continent = 1415, note = { "Blackrock Mountain dominates the northern skyline, giving almost every route across the Steppes the same great landmark. The approach from Redridge climbs into ash-dark country, where broken ridges and old fortifications interrupt the plain.", "Morgan's Vigil occupies the eastern heights for the Alliance; Flame Crest offers the Horde a foothold farther north. Between them lie Blackrock camps, dragonkin and the remains of older battles.", "The mountain is also the passage into Searing Gorge. From outside, it seems a solid wall at the end of the country. Inside, the scale of its bridges and chambers becomes the traveller's next problem." }, places = { { "Altar of Storms", 100, 150, 215, 280, 255 }, { "Blackrock Mountain", 220, 145, 380, 280, 254 }, { "Blackrock Pass", 680, 385, 825, 530, 2417 }, { "Blackrock Stronghold", 370, 160, 505, 310, 252 }, { "Draco'dar", 125, 330, 435, 545, 2421 }, { "Dreadmaul Rock", 745, 205, 885, 350, 249 }, { "Morgan's Vigil", 805, 350, 970, 515, 2418 }, { "Ruins of Thaurissan", 550, 145, 755, 315, 250 }, { "Terror Wing Path", 780, 115, 995, 365, 2420 }, { "The Pillar of Ash", 415, 325, 590, 430, 253 } } },
      [1429] = { name = "Elwynn Forest", continent = 1415, note = { "Elwynn's main road runs from Stormwind through Goldshire and east to Redridge. Northshire occupies a sheltered valley to the north, while the western crossing leads into Westfall. Farms, bridges and lakes give this country unusually clear bearings.", "The mines are less orderly than the fields above them: kobolds occupy Fargodeep and Jasperlode, and Defias activity reaches well into the forest. In the south-west, the Riverpaw camps make the open woodland around the river dangerous ground.", "Stormwind is never far away in miles. A farmer waiting for help with a mine or a camp may have a different measure of the distance." }, places = { { "Brackwell Pumpkin Patch", 615, 495, 735, 565, 62 }, { "Crystal Lake", 450, 380, 605, 475, 18 }, { "Eastvale Logging Camp", 775, 400, 900, 485, 88 }, { "Fargodeep Mine", 300, 510, 470, 615, 57 }, { "Forest's Edge", 200, 445, 300, 645, 60 }, { "Goldshire", 370, 400, 455, 465, 87 }, { "Jerod's Landing", 460, 495, 615, 615, 797 }, { "Northshire Valley", 425, 190, 600, 375, 9 }, { "Ridgepoint Tower", 790, 505, 915, 570, 798 }, { "Stone Cairn Lake", 675, 250, 830, 415, 86 }, { "Tower of Azora", 610, 400, 745, 490, 91 }, { "Valley of Heroes", 115, 120, 370, 355, 1617, 80 } } },
      [1430] = { name = "Deadwind Pass", continent = 1415, note = { "The road from Duskwood to the Swamp of Sorrows crosses Deadwind Pass between bare rock and deep drops. The main way is short enough on a map, but the dead trees and empty buildings give little reason to linger.", "A southern branch descends toward Karazhan and the abandoned village beneath it. The tower is sealed in these days. Its height makes an excellent landmark over country in which almost everything else seems to have stopped growing." }, places = { { "Deadman's Crossing", 315, 125, 590, 355, 2697 }, { "Karazhan", 335, 380, 520, 540, 2562 }, { "The Vice", 510, 325, 665, 540, 2561 } } },
      [1431] = { name = "Duskwood", continent = 1415, note = { "Duskwood's roads pass through a forest that gives little daylight to the ground. Darkshire is the principal refuge in the east, with the Night Watch holding its approaches. Deadwind Pass lies beyond it; the southern road descends toward Stranglethorn.", "To the west, Raven Hill and its cemetery occupy country far less secure than the map's familiar farm names suggest. The Rotting Orchard and abandoned houses preserve the shape of a settled valley without much of its old life.", "The roads still join the places they were built to serve. That makes them useful bearings, even when the destination has become somewhere a traveller would rather pass by." }, places = { { "Addle's Stead", 160, 415, 275, 510, 536 }, { "Brightwood Grove", 570, 165, 685, 380, 242 }, { "Darkshire", 710, 250, 835, 350, 42 }, { "Manor Mistmantle", 695, 195, 795, 255, 1098 }, { "Raven Hill", 155, 340, 260, 410, 94 }, { "Raven Hill Cemetery", 145, 210, 260, 350, 492 }, { "The Darkened Bank", 125, 85, 970, 200, 799 }, { "The Hushed Bank", 56, 191, 145, 403, 1097 }, { "The Rotting Orchard", 580, 430, 705, 545, 241 }, { "The Yorgen Farmstead", 445, 440, 540, 540, 245 }, { "Tranquil Gardens Cemetery", 755, 430, 850, 505, 121 }, { "Twilight Grove", 370, 145, 585, 395, 856 }, { "Vul'Gol Ogre Mound", 285, 435, 440, 545, 93 } } },
      [1432] = { name = "Loch Modan", continent = 1415, note = { "A long lake held back by the Stonewrought Dam, the finest piece of dwarven engineering outside Ironforge, and I will hear no argument. Thelsamar sits on the western shore on the road from Dun Morogh, and the road goes on north to the Wetlands and south to the Badlands.", "The Valley of Kings at the pass has stone kings to watch over it. The rest of the country needs watching: troggs in Stonesplinter Valley, kobolds in the mines, and ogres in the Mo'grosh Stronghold in the north-east hills.", "The high elves of the Farstrider Lodge keep to themselves and know the country better than any dwarf. Ask them before you go hunting." }, places = { { "Grizzlepaw Ridge", 395, 395, 510, 525, 936 }, { "Ironband's Excavation Site", 625, 380, 765, 495, 142 }, { "Mo'grosh Stronghold", 620, 105, 800, 230, 143 }, { "North Gate Pass", 160, 45, 290, 160, 838 }, { "Silver Stream Mine", 290, 90, 400, 200, 149 }, { "Stonesplinter Valley", 275, 430, 425, 610, 923 }, { "Stonewrought Dam", 380, 45, 580, 125, 146 }, { "The Farstrider Lodge", 790, 380, 875, 460, 147 }, { "The Loch", 405, 115, 600, 450, 556 }, { "Thelsamar", 300, 265, 400, 350, 144 }, { "Valley of Kings", 150, 400, 260, 585, 924 } } },
      [1433] = { name = "Redridge Mountains", continent = 1415, note = { "Lakeshire sits on the western shore of Lake Everstill, where bridges and roads join the approaches from Elwynn and Duskwood. The water gives the valley a broad, beautiful centre and an unusually clear set of bearings.", "The eastern heights are another matter. Stonewatch Keep is in Blackrock hands, and gnoll camps occupy the ridges between settled ground and the mountains.", "From Lakeshire, the far shore looks close enough to be part of the town's own country. The guards' view of it is much less peaceful." }, places = { { "Alther's Mill", 410, 233, 549, 337, 97 }, { "Galardell Valley", 626, 208, 798, 353, 1000, 96 }, { "Lake Everstill", 302, 338, 540, 461, 68 }, { "Lakeridge Highway", 219, 459, 528, 569, 1001 }, { "Lakeshire", 94, 263, 334, 342, 69 }, { "Redridge Canyons", 117, 131, 351, 252, 95, 98 }, { "Render's Camp", 275, 53, 408, 143, 996, 998 }, { "Render's Valley", 594, 476, 817, 581, 997 }, { "Stonewatch", 571, 338, 677, 422, 70, 999 }, { "Stonewatch Falls", 652, 407, 814, 491, 71 }, { "Three Corners", 53, 424, 186, 555, 1002 } } },
      [1434] = { name = "Stranglethorn Vale", continent = 1415, note = { "Stranglethorn runs from Duskwood's southern edge to Booty Bay through a long stretch of jungle. The road passes the northern expeditions and the Horde's Grom'gol before reaching the goblin port at the far end.", "Ruins and occupied camps lie close behind the trees: Kurzen's compound, troll settlements, Mosh'Ogg ground and the approaches to Zul'Gurub. A clearing offers a view without necessarily offering a safe halt.", "Booty Bay is built along steep rock around its harbour, with the boat to Ratchet waiting below the town's tiers. After so much jungle, a route measured across open water is a welcome change." }, places = { { "Bal'lal Ruins", 270, 115, 320, 150, 123 }, { "Balia'mah Ruins", 390, 185, 445, 230, 127 }, { "Bloodsail Compound", 220, 325, 320, 390, 1739 }, { "Booty Bay", 220, 460, 305, 530, 35 }, { "Crystalvein Mine", 380, 310, 440, 365, 310 }, { "Grom'gol Base Camp", 285, 160, 350, 205, 117 }, { "Gurubashi Arena", 250, 255, 340, 335, 1741 }, { "Jaguero Isle", 350, 510, 430, 590, 297 }, { "Kal'ai Ruins", 320, 120, 370, 160, 125 }, { "Kurzen's Compound", 415, 35, 495, 90, 101 }, { "Lake Nazferiti", 375, 100, 435, 150, 37 }, { "Mistvale Valley", 320, 395, 355, 465, 1737 }, { "Mizjah Ruins", 350, 180, 390, 215, 129 }, { "Mosh'Ogg Ogre Mound", 455, 160, 535, 240, 105 }, { "Nek'mani Wellspring", 230, 385, 285, 450, 1738 }, { "Nesingwary's Expedition", 305, 60, 380, 115, 100 }, { "Rebel Camp", 335, 20, 415, 55, 99 }, { "Ruins of Aboraz", 375, 375, 420, 415, 311 }, { "Ruins of Jubuwal", 335, 325, 380, 365, 477 }, { "Ruins of Zul'Kunda", 220, 55, 300, 110, 102 }, { "Ruins of Zul'Mamwe", 435, 250, 500, 315, 103 }, { "The Vile Reef", 180, 135, 305, 235, 104 }, { "Venture Co. Base Camp", 420, 100, 465, 165, 1740 }, { "Wild Shore", 300, 505, 350, 555, 43 }, { "Ziata'jai Ruins", 385, 235, 430, 315, 128 }, { "Zul'Gurub", 525, 50, 675, 200, 19 }, { "Zuuldaia Ruins", 190, 80, 235, 120, 122 } } },
      [1435] = { name = "Swamp of Sorrows", continent = 1415, note = { "The western road enters from Deadwind Pass and crosses the marsh toward Stonard, the Horde's principal settlement. A southern branch reaches the Blasted Lands. Beyond the road, shallow water repeatedly interrupts what appears to be solid ground.", "The Pool of Tears covers the Temple of Atal'Hakkar. Fallow Sanctuary lies farther east, while the Harborage shelters draenei refugees in the north. Reaching the coast means passing well beyond the last dependable stretch of road.", "The swamp gives little height from which to take a bearing. A temple submerged beneath a lake is a particularly unhelpful landmark for anyone trying to find the lake." }, places = { { "Fallow Sanctuary", 540, 60, 765, 240, 76 }, { "Itharius's Cave", 100, 350, 200, 490, 1777 }, { "Misty Reed Strand", 815, 75, 955, 630, 300 }, { "Misty Valley", 50, 190, 215, 290, 116 }, { "Pool of Tears", 620, 265, 805, 440, 74 }, { "Sorrowmurk", 775, 175, 905, 445, 1778 }, { "Splinterspear Junction", 150, 290, 340, 410, 1780 }, { "Stagalbog", 615, 455, 795, 600, 1797 }, { "Stonard", 370, 300, 585, 435, 75 }, { "The Harborage", 215, 190, 340, 290, 657 }, { "The Shifting Mire", 320, 160, 560, 305, 1798 } } },
      [1436] = { name = "Westfall", continent = 1415, note = { "Westfall's road crosses from Elwynn into open farmland and continues to Sentinel Hill. The People's Militia holds the tower, which remains a useful landmark over fields whose owners have often fled.", "Moonbrook lies farther south, with the Deadmines beneath it. Elsewhere, Defias camps and hostile harvest golems occupy country still divided by hedges and farm tracks.", "The lighthouse is a clear bearing from the western coast, though murloc camps interrupt the approach. There is ample room to see across Westfall; knowing what waits in the next field is the harder part." }, places = { { "Alexston Farmstead", 325, 295, 440, 405, 219 }, { "Demont's Place", 260, 420, 365, 510, 921 }, { "Furlbrow's Pumpkin Farm", 465, 100, 555, 185, 109 }, { "Gold Coast Quarry", 255, 230, 375, 325, 113 }, { "Jangolode Mine", 405, 125, 490, 200, 111 }, { "Moonbrook", 390, 370, 495, 505, 20 }, { "Saldean's Farm", 505, 180, 605, 255, 107 }, { "Sentinel Hill", 515, 280, 605, 385, 108 }, { "The Dagger Hills", 380, 490, 560, 565, 920 }, { "The Dead Acre", 575, 370, 675, 450, 917 }, { "The Dust Plains", 560, 450, 710, 520, 922 }, { "The Jansen Stead", 520, 75, 615, 160, 916 }, { "The Molsen Farm", 395, 200, 505, 285, 918 }, { "Westfall Lighthouse", 260, 530, 380, 620, 115 } } },
      [1437] = { name = "Wetlands", continent = 1415, note = { "Dun Algaz brings the Loch Modan road down into broad fens, where the main routes separate toward Menethil Harbor in the west and Thandol Span in the north. The raised road gives a firmer line through country divided by shallow water.", "Menethil's ships connect the Wetlands with Auberdine and Theramore. Inland, Dragonmaw camps occupy the hills, Dark Irons hold Dun Modr, and red dragonkin guard the approaches to Grim Batol in the east.", "Beyond the older dig at Whelgar's site, the new excavation reaches into ancient workings. Relics brought back to Whelgar give the League good reason to keep the approach on its maps.", "Off the road, reeds can hide the edge of a channel as readily as a crocolisk. The shortest route to the next rise may contain far more water than the map suggests." }, places = { { "Angerfang Encampment", 400, 270, 550, 375, 1036 }, { "Black Channel Marsh", 125, 285, 275, 370, 1018 }, { "Bluegill Marsh", 120, 205, 265, 280, 1022 }, { "Direforge Hill", 550, 150, 665, 285, 1016 }, { "Dun Modr", 445, 80, 545, 145, 205 }, { "Grim Batol", 611, 230, 995, 614, 1037, visit = true }, { "Ironbeard's Tomb", 385, 150, 510, 265, 309 }, { "Menethil Harbor", 70, 345, 135, 415, 150 }, { "Mosshide Fen", 565, 305, 675, 425, 1020 }, { "Raptor Ridge", 665, 210, 780, 300, 1017 }, { "Saltspray Glen", 275, 95, 410, 230, 1023 }, { "Sundown Marsh", 140, 140, 325, 240, 1024 }, { "The Green Belt", 485, 170, 590, 320, 1025 }, { "Thelgen Rock", 505, 405, 625, 515, 1021 }, { "Whelgar's Excavation Site", 310, 295, 410, 360, 118 } } },
      [1438] = { name = "Teldrassil", continent = 1414, note = { "Teldrassil carries an entire inhabited forest above the sea. The road runs from Shadowglen through Dolanaar to Darnassus, with branches into glades and barrow country that can feel far removed from an island's edge.", "Webwood and the Gnarlpine holdings interrupt the settled woods. Pools provide frequent landmarks, though their enclosed banks reveal little of the height beneath them.", "The way down is through Darnassus's portal to Rut'theran Village, where the boats leave from the roots. It is worth keeping that route in mind: a coast is not much use to a traveller when it lies so far below the road." }, places = { { "Ban'ethil Hollow", 420, 305, 510, 460, 736 }, { "Dolanaar", 495, 340, 610, 420, 186 }, { "Gnarlpine Hold", 400, 465, 480, 535, 261 }, { "Lake Al'Ameth", 495, 425, 660, 525, 259 }, { "Pools of Arlithrien", 375, 380, 435, 470, 478 }, { "Rut'theran Village", 550, 600, 565, 615, 702 }, { "Shadowglen", 535, 205, 660, 330, 188 }, { "Starbreeze Village", 605, 345, 710, 425, 260 }, { "The Oracle Glade", 350, 170, 410, 315, 264 }, { "Warrior's Terrace", 200, 290, 350, 480, 1660, 1662 }, { "Wellspring Lake", 415, 165, 525, 310, 266 } } },
      [1439] = { name = "Darkshore", continent = 1414, note = { "Darkshore is a long journey along a narrow coast. Auberdine gathers the roads and shipping in the middle, with boats across to Rut'theran Village and over the sea to Menethil Harbor. The southern road leads into Ashenvale.", "The shore and the inland woods offer very different lines of travel. Wrecks and murloc camps interrupt the beaches; inland lie the haunted ruins of Ameth'Aran and Bashal'Aran, the Blackwood camps and the tower of Althalaxx.", "The sea is a steady guide when the trees hide the road. It is also the reason so many broken ships have become landmarks." }, places = { { "Ameth'Aran", 395, 350, 460, 420, 447 }, { "Auberdine", 355, 255, 430, 330, 442 }, { "Bashal'Aran", 415, 215, 485, 270, 446 }, { "Cliffspring River", 485, 190, 590, 255, 456 }, { "Grove of the Ancients", 385, 475, 475, 555, 448 }, { "Remtravel's Excavation", 320, 540, 380, 600, 450 }, { "Ruins of Mathystra", 555, 60, 620, 160, 443 }, { "The Master's Glaive", 370, 555, 460, 630, 449 }, { "Tower of Althalaxx", 520, 145, 610, 205, 444 } } },
      [1440] = { name = "Ashenvale", continent = 1414, note = { "Ashenvale's main road runs through deep woodland to Astranaar, then east toward the Warsong camps and Azshara. Branches lead north into Darkshore, west through the mountain passage to Stonetalon, and south toward the Mor'shan Rampart.", "The settlements stand far enough apart for the forest to close around a traveller between them. On the coast, the Zoram Strand opens into naga-held ruins; inland, furbolg camps and the demonic ground around Felfire Hill make several inviting clearings poor stopping places.", "Astranaar's bridges and lake provide a welcome fixed point in so much timber. Beyond them, the view seldom reaches far enough to show the whole route ahead." }, places = { { "Astranaar", 310, 295, 435, 395, 415 }, { "Bough Shadow", 895, 200, 985, 285, 438 }, { "Fallen Sky Lake", 635, 505, 750, 590, 422 }, { "Felfire Hill", 750, 465, 915, 570, 434 }, { "Fire Scar Shrine", 235, 390, 300, 460, 417 }, { "Iris Lake", 430, 275, 500, 350, 424 }, { "Lake Falathim", 175, 230, 235, 310, 441 }, { "Maestra's Post", 250, 90, 335, 255, 413 }, { "Mystral Lake", 420, 430, 570, 550, 421 }, { "Night Run", 660, 340, 775, 450, 428 }, { "Raynewood Retreat", 560, 305, 660, 385, 426 }, { "Satyrnaar", 750, 290, 890, 355, 430 }, { "The Howling Vale", 500, 200, 625, 295, 419 }, { "The Ruins of Stardust", 295, 405, 375, 495, 418 }, { "The Shrine of Aessina", 175, 305, 270, 400, 416 }, { "The Zoram Strand", 45, 60, 215, 235, 414 }, { "Thistlefur Village", 335, 215, 405, 275, 2301 }, { "Warsong Lumber Camp", 855, 355, 970, 435, 437 } } },
      [1441] = { name = "Thousand Needles", continent = 1414, note = { "The Great Lift descends from the Barrens into a canyon crowded with stone pillars. Freewind Post stands on top of one, reached by lifts of its own; below, the road threads between cliffs toward the Shimmering Flats.", "Darkcloud Pinnacle is Grimtotem ground, while centaurs and harpies occupy other side canyons. The pillars make good landmarks until the next one hides them.", "Eastward, the land opens suddenly onto salt flats and the Mirage Raceway. Gnome and goblin machines fill a country broad enough, at last, to let a traveller see a long way without looking up." }, places = { { "Camp E'thok", 65, 40, 260, 195, 480 }, { "Darkcloud Pinnacle", 305, 190, 395, 295, 2097 }, { "Freewind Post", 400, 300, 525, 405, 484 }, { "Highperch", 70, 150, 200, 305, 482 }, { "Splithoof Crag", 400, 225, 560, 325, 481 }, { "The Great Lift", 275, 115, 370, 185, 485 }, { "The Screeching Canyon", 225, 235, 390, 400, 483 }, { "The Shimmering Flats", 660, 325, 910, 650, 439 }, { "Windbreak Canyon", 550, 285, 700, 450, 2303 } } },
      [1442] = { name = "Stonetalon Mountains", continent = 1414, note = { "Stonetalon's roads climb through narrow valleys, with Sun Rock Retreat in the middle of the range and Malaka'jin near the southern approaches. The night elves hold Stonetalon Peak far to the north.", "The Venture Company's cutting has opened great wounds in the forest. Farther west, the Charred Vale is burned ground occupied by harpies and other dangers. The Webwinder Path offers a more literal warning in its name.", "The mountain passage to Ashenvale and the roads down toward the Barrens and Desolace make this a place of crossings. Distance alone gives a poor estimate of a journey through so many turns and climbs." }, places = { { "Boulderslide Ravine", 600, 580, 700, 660, 2540 }, { "Camp Aparaje", 745, 600, 805, 635, 2538 }, { "Grimtotem Post", 700, 555, 815, 605, 2537 }, { "Malaka'jin", 695, 605, 765, 660, 2539 }, { "Mirkfallon Lake", 425, 220, 560, 325, 464 }, { "Sishir Canyon", 500, 465, 590, 535, 2541 }, { "Stonetalon Peak", 270, 30, 475, 150, 467 }, { "Sun Rock Retreat", 410, 345, 520, 435, 460 }, { "The Charred Vale", 245, 375, 395, 520, 465 }, { "Webwinder Path", 500, 315, 710, 600, 1076 }, { "Windshear Crag", 570, 240, 830, 435, 461 } } },
      [1443] = { name = "Desolace", continent = 1414, note = { "Desolace opens below Stonetalon in grey ridges and broad, exposed ground. Nijel's Point occupies the northern heights for the Alliance; Shadowprey Village lies down on the western coast for the Horde. The southern route reaches Feralas.", "Centaur territories fill much of the interior, with the Kodo Graveyard among them. Thunder Axe Fortress and Mannoroc Coven mark hostile ground of another kind. On the coast, the country drops toward naga-held water.", "The bones make the graveyard conspicuous from a distance. Shadowprey's waterfront gives the eye something gentler to rest on: a settlement built toward the sea rather than another camp in the dust." }, places = { { "Ethel Rethor", 345, 135, 475, 275, 2405 }, { "Gelkis Village", 320, 540, 450, 650, 606 }, { "Kodo Graveyard", 435, 325, 580, 450, 596 }, { "Kolkar Village", 695, 275, 795, 375, 609 }, { "Kormek's Hut", 590, 230, 700, 310, 2407 }, { "Magram Village", 650, 425, 775, 550, 604 }, { "Mannoroc Coven", 455, 470, 615, 590, 602 }, { "Nijel's Point", 600, 25, 700, 100, 608 }, { "Ranazjar Isle", 255, 25, 325, 85, 2406 }, { "Sargeron", 695, 95, 825, 210, 603 }, { "Shadowbreak Ravine", 760, 485, 850, 575, 2198 }, { "Shadowprey Village", 195, 420, 315, 520, 2408 }, { "Tethris Aran", 495, 50, 595, 115, 2404 }, { "Thunder Axe Fortress", 490, 150, 600, 225, 599 }, { "Valley of Spears", 250, 255, 415, 440, 607 } } },
      [1444] = { name = "Feralas", continent = 1414, note = { "Feralas closes around the road in great trunks and dense undergrowth. The northern passage comes down from Desolace; eastward, the route reaches Camp Mojache and continues toward Thousand Needles.", "Feathermoon Stronghold stands offshore on Sardor Isle, reached by boat from the western coast. Inland, Dire Maul rises above the forest, with ogres occupying much of the ruined city. Dream Bough's great tree marks dragon-held ground farther north.", "The canopy can hide a substantial slope until the road begins climbing it. A survey of Feralas needs room for height as well as distance." }, places = { { "Camp Mojache", 715, 250, 795, 315, 1099 }, { "Dire Maul", 525, 235, 655, 325, 2577 }, { "Dream Bough", 490, 40, 540, 95, 1111 }, { "Feral Scar Vale", 510, 350, 580, 410, 1105 }, { "Frayfeather Highlands", 505, 415, 570, 535, 1106 }, { "Gordunni Outpost", 725, 175, 825, 240, 1103 }, { "Grimtotem Compound", 650, 220, 710, 320, 1100 }, { "Isle of Dread", 225, 410, 370, 645, 1121 }, { "Lower Wilds", 800, 240, 925, 335, 1137 }, { "Oneiros", 520, 95, 575, 130, 1113 }, { "Ruins of Isildien", 565, 375, 665, 520, 2522 }, { "Ruins of Ravenwind", 360, 45, 435, 100, 1114 }, { "Sardor Isle", 235, 280, 370, 390, 1120 }, { "The Forgotten Coast", 430, 275, 500, 555, 1108 }, { "The Twin Colossals", 395, 100, 550, 240, 1119 }, { "The Writhing Deep", 645, 340, 815, 475, 1101 } } },
      [1445] = { name = "Dustwallow Marsh", continent = 1414, note = { "The Barrens road enters Dustwallow through reeds and shallow water, eventually reaching Theramore's causeway and harbour. Menethil-bound ships leave from the island city. Brackenwall Village, a Horde settlement with Stonemaul ogres among its inhabitants, stands in the north-western marsh.", "Onyxia's country lies south in the Wyrmbog. Elsewhere, channels and low banks break up ground that looks continuous from a distance. A bend in the road often provides a surer bearing than the trees, which have an unfortunate resemblance to one another.", "From Theramore's stonework, the mainland looks very close. After a few turns through the marsh, the city can seem to have vanished behind it." }, places = { { "Alcaz Island", 695, 55, 820, 180, 2079 }, { "Brackenwall Village", 305, 70, 435, 235, 496, 499, 507 }, { "The Den of Flame", 315, 345, 425, 475, 509, 508, 498, 510 }, { "The Quagmire", 320, 240, 570, 410, 2302, 501, 517 }, { "Theramore Isle", 615, 280, 750, 405, 513, 503 }, { "Witch Hill", 445, 60, 635, 245, 502, 518, 504, 516 }, { "Wyrmbog", 440, 435, 615, 570, 511, 517 } } },
      [1446] = { name = "Tanaris", continent = 1414, note = { "The descent from Thousand Needles reaches Gadgetzan near the northern end of Tanaris. Its walls and Steamwheedle Port on the eastern coast are useful fixed points in a desert whose southern reaches are much less settled.", "Zul'Farrak stands in the north-west, Dunemaul ogres occupy the interior, and Lost Rigger Cove shelters pirates behind the eastern hills. The Caverns of Time open among the mountains farther south-east.", "The westward route eventually descends into Un'Goro. From the rim, the green crater looks like another country entirely, which is an unusually agreeable discovery after so much sand." }, places = { { "Abyssal Sands", 410, 240, 505, 330, 1939 }, { "Broken Pillar", 500, 275, 565, 335, 1938 }, { "Caverns of Time", 595, 295, 690, 365, 2300 }, { "Dunemaul Compound", 380, 335, 460, 415, 983 }, { "Eastmoon Ruins", 435, 410, 500, 460, 984 }, { "Gadgetzan", 460, 140, 565, 225, 976 }, { "Land's End Beach", 480, 565, 620, 660, 987 }, { "Lost Rigger Cove", 675, 255, 760, 375, 1336 }, { "Noonshade Ruins", 570, 140, 630, 190, 1937 }, { "Sandsorrow Watch", 365, 155, 435, 225, 979 }, { "Southbreak Shore", 570, 365, 680, 430, 1940 }, { "Southmoon Ruins", 365, 445, 440, 510, 992 }, { "Steamwheedle Port", 630, 110, 710, 175, 977 }, { "The Gaping Chasm", 490, 415, 600, 530, 981 }, { "The Noxious Lair", 310, 255, 385, 355, 982 }, { "Thistleshrub Valley", 245, 360, 370, 475, 980 }, { "Valley of the Watchers", 330, 490, 410, 585, 990 }, { "Waterspring Field", 550, 210, 645, 295, 985 }, { "Zalashji's Den", 640, 190, 700, 255, 986 }, { "Zul'Farrak", 300, 25, 450, 145, 978 } } },
      [1447] = { name = "Azshara", continent = 1414, note = { "The road enters from Ashenvale above a coast of broken temples and red-gold trees. Talrendis Point and Valormok offer small footholds near the western approach; farther east, the hills fall steeply toward the Bay of Storms.", "Naga occupy much of the shore, while satyr camps and elven expeditions hold ground among the ruins. Azuregos ranges the south. A direct line on the map can conceal both a cliff and the long way around it.", "The great stone gate in the northern hills leads to Blackmaw Hold, home to a corrupted furbolg tribe. The Timbermaw tunnels to Moonglade and Winterspring remain well west of here, in Felwood." }, places = { { "Bay of Storms", 505, 255, 675, 475, 1227 }, { "Bitter Reaches", 685, 80, 850, 180, 2497 }, { "Forlorn Ridge", 220, 425, 370, 530, 1233 }, { "Haldarr Encampment", 165, 370, 250, 435, 1236 }, { "Jagged Reef", 400, 35, 880, 115, 1230 }, { "Lake Mennar", 375, 490, 490, 580, 1234 }, { "Legashi Encampment", 495, 90, 665, 150, 1219 }, { "Ravencrest Monument", 660, 535, 755, 600, 1232 }, { "Ruins of Eldarath", 305, 310, 430, 415, 1221 }, { "Shadowsong Shrine", 125, 455, 225, 545, 1235 }, { "Southridge Beach", 440, 420, 730, 540, 1231 }, { "Temple of Arkkoran", 715, 225, 820, 325, 1226 }, { "Thalassian Base Camp", 535, 160, 685, 225, 1220 }, { "The Ruined Reaches", 440, 580, 725, 645, 1256 }, { "The Shattered Strand", 430, 245, 485, 370, 1228 }, { "Timbermaw Hold", 250, 106, 506, 394, 1769, visit = true }, { "Tower of Eldara", 850, 160, 920, 245, 1229 }, { "Ursolan", 430, 150, 510, 230, 1225 }, { "Valormok", 165, 310, 265, 365, 1237 } } },
      [1448] = { name = "Felwood", continent = 1414, note = { "Felwood's road runs north from Ashenvale through a forest whose dead and sickened trees leave long gaps in the canopy. Emerald Sanctuary lies near the southern approach; Bloodvenom Post and Talonbranch Glade offer separate footholds farther along the valley.", "Jaedenar and the Jadefire camps occupy some of the most deeply corrupted ground. At the northern end, the Timbermaw tunnels lead into Moonglade and Winterspring, provided their guards allow passage.", "A green pool here gives no comfort to a thirsty-looking landscape. The colour belongs to the damage, and often shows through the trees before the pool itself can be seen." }, places = { { "Bloodvenom Falls", 360, 295, 490, 355, 1765 }, { "Deadwood Village", 450, 580, 535, 640, 1761 }, { "Emerald Sanctuary", 470, 505, 565, 560, 2479 }, { "Felpaw Village", 585, 35, 685, 110, 1762 }, { "Irontree Woods", 455, 120, 550, 195, 1767 }, { "Jadefire Glen", 370, 510, 455, 595, 2480 }, { "Jadefire Run", 370, 85, 455, 155, 2618 }, { "Jaedenar", 300, 375, 430, 425, 1763 }, { "Morlos'Aran", 540, 560, 615, 615, 2478 }, { "Ruins of Constellas", 335, 425, 425, 500, 2481 }, { "Shatter Scar Vale", 370, 175, 475, 295, 1766 }, { "Talonbranch Glade ", 585, 130, 660, 195, 1998 } } },
      [1449] = { name = "Un'Goro Crater", continent = 1414, note = { "The path down from Tanaris reveals Un'Goro all at once: dense jungle around Fire Plume Ridge, with tar pits and hot springs breaking the green. Marshal's Refuge lies against the northern rim; the route out toward Silithus climbs away in the north-west.", "The central volcano is an excellent bearing and difficult ground. Away from it, the canopy hides raptors, devilsaurs and the silithid territory of the Slithering Scar. The crater is easier to overlook from above than to cross below.", "The Shapers' Terrace gives the crater's Titan traces a place on the map beside the pylons and scattered crystals. A name for one ancient site leaves a great deal of jungle unaccounted for." }, places = { { "Fire Plume Ridge", 415, 250, 595, 415, 537 }, { "Golakka Hot Springs", 215, 235, 390, 435, 543 }, { "Ironstone Plateau", 625, 145, 825, 320, 1943 }, { "Lakkari Tar Pits", 355, 25, 660, 250, 538 }, { "Terror Run", 300, 415, 445, 575, 539 }, { "The Marshlands", 615, 305, 780, 540, 1942 }, { "The Slithering Scar", 440, 470, 595, 600, 540 } } },
      [1450] = { name = "Moonglade", continent = 1414, note = { "Lake Elune'ara lies at the centre of Moonglade, with Nighthaven on its shore and Keeper Remulos's shrine nearby. Druids arrive by their own magic; other travellers commonly reach the valley through the Timbermaw tunnels from Felwood.", "The Cenarion Circle welcomes both factions here, and the Lunar Festival brings visitors from much farther away. The quiet is real, though the struggle around the Emerald Dream has reached even this valley.", "For a surveyor, the lake is the welcome constant: a broad, open bearing after the enclosed mountain passage." }, places = { { "Moonglade", 244, 89, 820, 601, 493, 656, 2362, 2361, visit = true } } },
      [1451] = { name = "Silithus", continent = 1414, note = { "The path from Un'Goro reaches Silithus at the north-eastern edge of a broad desert. Cenarion Hold rises above the interior, giving travellers a fortified point from which to judge the distances between hives.", "The Twilight's Hammer occupies camps across the waste, while the great Scarab Wall marks Ahn'Qiraj in the south. Silithid mounds interrupt what can otherwise look like open sand.", "Southwind Village remains a recognisable settlement on the map and a ruin on the ground. The roads and towers are sparse enough that a single standing building can matter a great deal to one's bearings." }, places = { { "Hive'Ashi", 385, 100, 515, 225, 2742 }, { "Hive'Regal", 490, 425, 655, 650, 2744 }, { "Hive'Zora", 165, 310, 330, 470, 2743 }, { "Southwind Village", 585, 315, 665, 395, 2738 }, { "The Crystal Vale", 150, 50, 315, 185, 2740 }, { "The Scarab Wall", 220, 615, 360, 655, 2737 }, { "Twilight Base Camp", 343, 196, 663, 452, 2739, visit = true } } },
      [1452] = { name = "Winterspring", continent = 1414, note = { "The Timbermaw passage opens into Winterspring's broad snowfields, with Everlook gathering trade near the centre. The goblins' town gives both factions a roof and a meeting of routes among the mountains.", "Starfall Village lies to the west, Mazthoril's blue dragonkin hold the caves to the south, and yeti country rises beyond the Ice Thistle Hills. Winterfall camps interrupt other approaches through the snow.", "Darkwhisper Gorge cuts into the far south, where demons make a bleak boundary to the valley. The hot springs are kinder landmarks: dark open water and rising steam against a great deal of white." }, places = { { "Darkwhisper Gorge", 490, 500, 670, 610, 2256, 16005 }, { "Everlook", 565, 220, 655, 285, 2255 }, { "Frostfire Hot Springs", 275, 220, 395, 270, 2246 }, { "Frostsaber Rock", 440, 55, 550, 115, 2241 }, { "Frostwhisper Gorge", 575, 420, 665, 495, 2249 }, { "Ice Thistle Hills", 650, 265, 715, 345, 2247 }, { "Lake Kel'Theril", 485, 250, 580, 330, 2251 }, { "Mazthoril", 555, 360, 615, 415, 2245 }, { "Owl Wing Thicket", 620, 380, 690, 445, 2250 }, { "Starfall Village", 445, 160, 550, 220, 2253 }, { "The Hidden Grove", 600, 80, 695, 150, 2242 }, { "Timbermaw Post", 365, 270, 440, 310, 2243 }, { "Winterfall Village", 650, 220, 720, 270, 2244 } } },
      [1453] = { name = "Stormwind City", continent = 1415, note = { "Stormwind's gate brings the Elwynn road past the statues of the Valley of Heroes and into the Trade District. Canals divide the quarters, with bridges doing much of the work a broad avenue would do in another city.", "Gryphons leave from the Trade District, and the Deeprun Tram connects the Dwarven District with Ironforge. The Cathedral is an easy landmark above the roofs; the Stockade is a less reassuring one beside the water.", "The city's white stone is still an impressive answer to its earlier ruin. Getting across it efficiently requires a little more attention to the bridges than to the skyline." }, places = {  } },
      [1454] = { name = "Orgrimmar", continent = 1414, note = { "Orgrimmar follows the folds of a red-rock canyon, with its main gate opening south into Durotar. Ramps and passages join the valleys inside; two destinations close together on a flat map may require a long climb between them.", "Grommash Hold stands in the Valley of Wisdom, while the city's wind riders leave from a high tower. Outside the walls, zeppelins connect the capital with the Undercity and Grom'gol.", "The canyon is part of the fortress as much as the built walls are. Its shape is easiest to understand from above, which is convenient once a traveller has found the wind riders." }, places = {  } },
      [1455] = { name = "Ironforge", continent = 1415, note = { "Ironforge's gate opens from the snow into a city arranged around the Great Forge. The main ring joins the Commons, the High Seat, Tinker Town and the Hall of Explorers; knowing which direction to take around it saves a good deal of walking.", "The Deeprun Tram leaves from Tinker Town for Stormwind, and gryphons depart beside the Great Forge. The League's hall provides a quieter destination, though the exhibits occasionally attract as much argument as the auction house.", "Below the city, the caverns beneath Old Ironforge lead to the Hall of Thanes. Dark Iron intruders have found a way into its lower vaults. The city has acquired another frontier directly below the king's feet." }, places = {  } },
      [1456] = { name = "Thunder Bluff", continent = 1414, note = { "The tauren's city on the mesas of northern Mulgore, joined by rope bridges and reached by great lifts from the plain below.", "Each rise has its purpose: Elder Rise for the elders and the druids, Spirit Rise for the shamans and the priests, Hunter Rise for the hunters and the warriors. The bank and the auction house are on the central rise, and the wind riders fly from the tower.", "The bridges sway. Do not look down, and do not run." }, places = {  } },
      [1457] = { name = "Darnassus", continent = 1414, note = { "Darnassus opens around water and broad bridges high in Teldrassil. The Temple of the Moon gives the southern part of the city its great landmark, while traders and craftspeople occupy the terraces farther north.", "The road east leads to Dolanaar. At the city's western side, the portal provides passage down to Rut'theran Village and the boats below. A surveyor used to measuring a city's height from the ground has some adjusting to do here." }, places = {  } },
      [1458] = { name = "Undercity", continent = 1415, note = { "The Undercity lies beneath Lordaeron's ruined capital, reached by lifts below the old throne room or through the outer sewer approach. Inside, circular passages and green canals connect the quarters.", "The central bank is a useful bearing. The Royal Quarter and the apothecaries' work lie deeper within the city; getting there requires attention to levels as well as turns.", "Above ground, the zeppelin towers stand outside the ruins. A traveller arriving by air can have a very short walk to the city and still spend some time finding the right way down." }, places = {  } },
      [2482] = { name = "Mount Hyjal", continent = 1414, places = { { "Cradle of Tranquility", 267, 227, 410, 338, 17145 }, { "Dae'gun", 451, 170, 640, 328, 16866 }, { "Elderwild", 80, 266, 198, 400, 16848 }, { "Felblood Scar", 387, 440, 538, 586, 17050 }, { "Malorne's Retreat", 207, 423, 371, 520, 17144 }, { "Mourning's Rest", 191, 300, 293, 404, 16868 }, { "Shrine of Aviana", 437, 355, 578, 435, 16867 }, { "Summit of Eternity", 677, 125, 895, 345, 16849 }, { "Tainted Foothills", 592, 404, 822, 571, 16853 } } },
      [2521] = { name = "Zephras Isle", continent = 0, note = { "Zephras is an inhabited island suspended in Skywall. Valanaar occupies the south-eastern edge, with the High Elder's seat and the skydocks. Ban'aethal in the north has been evacuated as the pylons sustaining the island fail.", "The southern farms give way to the Shen'dar Highlands, then to villages, shrines and Shadowgale Forest. On ordinary ground a broken road is an inconvenience; here the ground itself has become part of the survey's uncertainty.", "Skycutters leave Valanaar for Dalaran and Mulgore. The routes to Anvilas and Siroccas have fallen silent, leaving those other islands beyond the traveller's present bearings." }, places = { { "East Pylon Watchtower", 667, 430, 735, 467, 17675 }, { "Fairweather Stables", 521, 525, 561, 560, 17684 }, { "Falaath Village", 461, 338, 538, 396, 16636 }, { "Gustberry Lowlands", 539, 417, 664, 473, 16626 }, { "Overlook Standing Stones", 461, 443, 502, 480, 17677 }, { "Rohashi Spires", 686, 293, 738, 369, 16630 }, { "Ruins of Ban'aethal", 548, 136, 615, 242, 16833 }, { "Shadowgale Forest", 542, 239, 667, 280, 16631 }, { "Shen'dar Highlands", 435, 393, 550, 435, 16623 }, { "Shen'dar Village", 404, 273, 487, 323, 16624 }, { "Shrine of Akir", 566, 298, 682, 374, 16629 }, { "Thendal Grove", 339, 177, 485, 218, 16622 }, { "Thendal Standing Stones", 465, 105, 513, 144, 17678, 16635 }, { "Thendal Village", 403, 118, 455, 176, 16635 }, { "Valanaar", 563, 472, 693, 579, 16638, 16628 }, { "West Pylon Watchtower", 382, 405, 432, 450, 17674 }, { "Windfield Orchard", 435, 521, 502, 574, 16663 }, { "Windsong Lake", 476, 291, 562, 341, 16625 }, { "Windsong Standing Stones", 434, 242, 483, 276, 17676 } } },
      [2548] = { name = "Riverglades", continent = 1415, places = { { "Bolder'ok", 593, 52, 723, 167, 16726 }, { "Bristle Hills", 197, 361, 350, 475, 16737 }, { "Elbrim's Farm", 497, 273, 551, 335, 16734 }, { "Farholde Keep", 594, 514, 704, 594, 16724 }, { "Krol'dok Stronghold", 361, 110, 529, 244, 17780 }, { "Meadowsbrook", 409, 513, 489, 569, 16735 }, { "Powderfuse Port", 701, 309, 833, 383, 16727 }, { "Rog'mar", 550, 279, 627, 336, 16743 }, { "Sunnyglade", 426, 288, 497, 397, 16723 }, { "Terral's Watch", 572, 407, 631, 452, 16729 }, { "Turner's Logging Camp", 345, 371, 418, 444, 16736 }, { "Twilight's Shroud", 219, 240, 333, 347, 16685 }, { "Wheeler's Grange", 499, 483, 588, 554, 16725 }, { "Windstead", 707, 170, 820, 287, 16731 } } },
      [2652] = { name = "Shen'dralas", continent = 1414, places = { { "Bristleback Retreat", 583, 0, 917, 415, 16677, visit = true }, { "Evenshade's Overlook", 150, 178, 466, 479, 16678, visit = true }, { "Forlorn Gardens", 570, 323, 887, 654, 16742, visit = true }, { "Magram Front", 495, 255, 752, 484, 16675, visit = true }, { "Outcast Hideaway", 125, 362, 469, 668, 16676, visit = true }, { "Shen'dralas", 339, 180, 666, 668, 16651, visit = true }, { "Valley of Bones", 81, 0, 701, 344, 2657, visit = true } } },
    },
  },
  -- the herbs (item id = { name, skill, zones (uiMaps), dungeons, inside: in
  -- another herb's node }), by the Herbalism skill they need; their nodes (game
  -- object id = an herb it gives); the fish (item id = { name, kind, zones,
  -- subzones, dungeons, season }), the weighed catches (item id = { the kind's
  -- entry, pounds }), and every school (fishing hole object id)
  flora = {
    herbs = {
      [2449] = { name = "Earthroot", skill = 15, zones = { 1413, 1411, 1426, 1420, 1429, 1433, 1436, 1412, 1438, 1439, 1421 }, dungeons = { "Wailing Caverns" }, note = { "Earthroot turns up across the settled lands and even within the Wailing Caverns. It is one of the first roots an herbalist learns to recognise.", "The Elixir of Lion's Strength and the Elixir of Minor Fortitude both begin with it. Such imposing names have modest ingredients, which is a comfort to an apprentice." } },
      [2447] = { name = "Peacebloom", skill = 1, zones = { 1413, 1411, 1420, 1412, 1426, 1438, 1429, 1421, 1439, 1432, 1436 }, dungeons = {  }, note = { "Peacebloom is a familiar flower along the first roads out of home, and useful long after an herbalist has learned rarer names.", "With Silverleaf it makes a Minor Healing Potion. There is something agreeable about finding the beginnings of a remedy in country where an apprentice can still recognise the way back." } },
      [765] = { name = "Silverleaf", skill = 1, zones = { 1411, 1413, 1432, 1412, 1429, 1420, 1439, 1426, 1438, 1421, 1436 }, dungeons = {  }, note = { "Silverleaf belongs in the same early gathering satchel as Peacebloom. A plant need not be rare to become indispensable to the workbench.", "Minor healing and mana draughts both call for it. The two uses explain why an alchemist who has gathered plenty can discover, quite shortly, that plenty was not enough." } },
      [785] = { name = "Mageroyal", skill = 50, zones = { 1413, 1440, 1439, 1436, 1421, 1433, 1411, 1432, 1431, 1437 }, dungeons = {  }, note = { "Mageroyal is a useful find along the roads beyond the first settlements. Swiftthistle is sometimes gathered with it, giving a single stop a second reward.", "Alchemists use Mageroyal in mana draughts and the Elixir of Wisdom. The name sets a high expectation; the work it does for a young spellcaster is quite sufficient." } },
      [2450] = { name = "Briarthorn", skill = 70, zones = { 1413, 1431, 1440, 1436, 1439, 1437, 1424, 1433, 1421, 1442, 1432 }, dungeons = { "Razorfen Kraul" }, note = { "Briarthorn is familiar in the Barrens and the wooded country across the sea. Swiftthistle may come away with the gathered stems.", "Healing draughts and Rage Potions both call for it. The same bundle can therefore help somebody recover from a fight or prepare to begin another." } },
      [2452] = { name = "Swiftthistle", skill = 50, zones = { 1413, 1440, 1431, 1439, 1436, 1433, 1421, 1437, 1424, 1432 }, dungeons = { "Razorfen Kraul" }, inside = true, note = { "Swiftthistle comes with Mageroyal and Briarthorn rather than from a patch of its own. An herbalist looking for it must pay attention to what the other gathering yields.", "Rogues brew Thistle Tea from it, while alchemists use it for swiftness and swimming draughts." } },
      [2453] = { name = "Bruiseweed", skill = 100, zones = { 1442, 1413, 1440, 1433, 1437, 1424, 1436, 1431, 1441, 1432, 1443, 1421, 1439 }, dungeons = { "Blackfathom Deeps", "Wailing Caverns" }, note = { "Bruiseweed is widespread enough to become a regular part of the gathering round. The Wailing Caverns and Blackfathom Deeps have it too, for those whose errands lead below ground.", "Healing Potions and the Elixir of Poison Resistance give it dependable work." } },
      [3820] = { name = "Stranglekelp", skill = 85, zones = { 1434, 1440, 1437, 1439, 1424, 1413, 1436, 1444, 1443 }, dungeons = { "Blackfathom Deeps", "Maraudon" }, note = { "Stranglekelp takes the herbalist away from the path and into coastal water. The gathering itself makes a good argument for knowing what is growing below the surface.", "An Elixir of Water Breathing is one of its uses, along with mana draughts and Free Action Potions. The plant supplies a remedy for an inconvenience encountered while collecting it." } },
      [3355] = { name = "Wild Steelbloom", skill = 115, zones = { 1417, 1442, 1434, 1437, 1441, 1413, 1440, 1418, 1416, 1424 }, dungeons = {  }, note = { "Wild Steelbloom is a familiar name to herbalists working the hills of Arathi and the rocky country of Stonetalon.", "The Elixir of Defense and the Elixir of Fortitude both use it. Armour is the smith's business, but the alchemist has a few contributions to make before the traveller buckles it on." } },
      [3369] = { name = "Grave Moss", skill = 120, zones = { 1431, 1443, 1437, 1417, 1416 }, dungeons = { "Razorfen Downs" }, note = { "Grave Moss is gathered in places where an herbalist is unlikely to feel entirely alone: Duskwood, Desolace and the burial ground of Razorfen Downs among them.", "Shadow Oil and Shadow Protection Potions call for it. The uses are well suited to the errands that bring a gatherer among the graves." } },
      [3356] = { name = "Kingsblood", skill = 125, zones = { 1434, 1437, 1440, 1424, 1413, 1431, 1417, 1442, 1418, 1443, 1441, 1416 }, dungeons = { "Wailing Caverns" }, note = { "Kingsblood occurs across a wide stretch of country, from wooded hills to the dry interior of Kalimdor. Its value does not depend on a difficult search.", "Greater healing draughts and mana potions both use it, and leatherworkers need it for Herbalist's Gloves. A gathering herb that helps make gathering gloves has a pleasing place in the trade." } },
      [3357] = { name = "Liferoot", skill = 150, zones = { 1434, 1437, 1417, 1416, 1444, 1445, 1424, 1435, 1443, 1425, 1440 }, dungeons = { "Scarlet Monastery", "Wailing Caverns" }, note = { "Liferoot is found in wet country on both continents, with the marshes and river lands offering much of the gathering.", "Greater Healing Potions and the Elixir of Waterwalking call for it." } },
      [3818] = { name = "Fadeleaf", skill = 160, zones = { 1417, 1435, 1416, 1434, 1425, 1418, 1445 }, dungeons = { "Razorfen Kraul", "Scarlet Monastery" }, note = { "Fadeleaf is gathered through the middle lands, with patches inside the Scarlet Monastery and Razorfen Kraul as well.", "Rogues prepare Blinding Powder from it. Alchemists put it into potions for becoming unseen and for detecting what is unseen: the same herb contributes to both sides of a difficult encounter." } },
      [3821] = { name = "Goldthorn", skill = 170, zones = { 1434, 1417, 1435, 1416, 1425, 1444, 1418 }, dungeons = { "Razorfen Downs", "Scarlet Monastery" }, note = { "Goldthorn earns a place in a working satchel through the variety of its uses. Its gathering country includes Arathi's hills and the forests of Feralas.", "Greater mana draughts, agility elixirs and Frost Protection Potions all call for it." } },
      [3358] = { name = "Khadgar's Whisker", skill = 185, zones = { 1434, 1417, 1435, 1416, 1444, 1425, 1418, 1445 }, dungeons = {  }, note = { "Khadgar's Whisker has a name a traveller is likely to remember, even before learning where to look for it. The herb occurs in several of the wooded and marshy lands.", "Greater Mana Potions and the Elixir of Greater Intellect use it, as does Frost Oil. The archmage's name has found its way onto a very busy shelf." } },
      [3819] = { name = "Wintersbite", skill = 195, zones = { 1416 }, dungeons = {  }, note = { "Wintersbite gives an herbalist a particular journey: into the snow of the Alterac Mountains. A familiar plant is welcome company in country where the paths are easily lost.", "Frost Oil, Frost Protection Potions and the Elixir of Frost Power all call for it. The mountain herb has work on either side of the struggle with cold." } },
      [8153] = { name = "Wildvine", skill = 210, zones = { 1447, 1425, 1446, 1444, 1434, 1440 }, dungeons = {  }, inside = true, note = { "Wildvine is gathered with Purple Lotus, an extra find in country already worth searching for the flower.", "Leatherworkers need it for wild leather and tailors for dreamweave. The flower and its companion find work on quite different benches." } },
      [4625] = { name = "Firebloom", skill = 205, zones = { 1446, 1427, 1418 }, dungeons = {  }, note = { "Firebloom belongs to the gathering routes through Tanaris, the Badlands and Searing Gorge. None is gentle country in which to stop and fill a satchel.", "Goblin Rocket Fuel and Oil of Immolation give a fair impression of its uses. The Philosophers' Stone calls for it too, for alchemists with a different ambition for the same bundle." } },
      [8831] = { name = "Purple Lotus", skill = 210, zones = { 1447, 1425, 1446, 1444, 1434, 1440 }, dungeons = { "Zul'Gurub" }, note = { "Purple Lotus grows in scattered lands on both continents, and sometimes yields Wildvine with the gathering.", "Dreamless Sleep Potions and the Elixir of Dream Vision both use it. An alchemist can offer a night without dreams or a journey made through one, depending on what accompanies the lotus in the vial." } },
      [8836] = { name = "Arthas' Tears", skill = 220, zones = { 1422, 1423, 1448 }, dungeons = { "Razorfen Downs" }, note = { "Arthas' Tears grows in the Plaguelands and Felwood, and is found within Razorfen Downs. The name is a sombre one to learn among so many ruined fields.", "The Elixir of Detect Undead and Gift of Arthas are its two familiar preparations. Neither does much to lighten the associations of a bundle brought back from that country." } },
      [8838] = { name = "Sungrass", skill = 230, zones = { 1447, 1425, 1444, 1423, 1449, 1428, 1422, 1448 }, dungeons = { "Zul'Gurub" }, note = { "Sungrass remains a welcome find in such troubled country as Felwood and the Plaguelands, as well as in greener lands farther south.", "Superior healing and mana draughts both use it." } },
      [8839] = { name = "Blindweed", skill = 235, zones = { 1435, 1449 }, dungeons = { "Maraudon" }, note = { "Blindweed leads a gatherer through the Swamp of Sorrows and Un'Goro, with another supply below ground in Maraudon.", "Superior Mana Potions and the Arcane Elixir call for it. In Gift of Arthas it accompanies Arthas' Tears." } },
      [8845] = { name = "Ghost Mushroom", skill = 245, zones = { 1425, 1443 }, dungeons = { "Dire Maul", "Maraudon" }, note = { "Ghost Mushrooms make cave country worth a careful search. The Hinterlands and Desolace have them, with more found inside Maraudon and Dire Maul.", "Alchemists use them for invisibility and shadow power, but also make Ghost Dye for tailors. A fungus brought out of the dark can finish its journey as the colour of a garment." } },
      [8846] = { name = "Gromsblood", skill = 250, zones = { 1448, 1443, 1419 }, dungeons = { "Dire Maul" }, note = { "Gromsblood is found through the tainted ground of Felwood, near the Dark Portal and within Dire Maul. The gathering route passes some of the Legion's most enduring marks on the world.", "The Flask of the Titans and the Elixir of Brute Force both call for it. So does the Elixir of Demonslaying, a particularly satisfying use for something gathered in such company." } },
      [13464] = { name = "Golden Sansam", skill = 260, zones = { 1449, 1447, 1423, 1448, 1425, 1428, 1444 }, dungeons = { "Zul'Gurub" }, note = { "Golden Sansam is gathered in Un'Goro and Azshara, and through such damaged country as Felwood and the Eastern Plaguelands.", "Major healing and rejuvenation draughts use it. The healing supplies brought back from those places have no shortage of work awaiting them." } },
      [13463] = { name = "Dreamfoil", skill = 270, zones = { 1447, 1423, 1449, 1428, 1448, 1422, 1451 }, dungeons = { "Dire Maul", "Zul'Gurub" }, note = { "Dreamfoil is gathered among Azshara's ruins and within Dire Maul, as well as in the scarred lands around Blackrock.", "Greater Protection Potions use it against fire, frost, nature, shadow and arcane harm. The Flask of Distilled Wisdom needs it too." } },
      [13465] = { name = "Mountain Silversage", skill = 280, zones = { 1452, 1449, 1447, 1428, 1423 }, dungeons = { "Zul'Gurub" }, note = { "Mountain Silversage is gathered in Winterspring and Un'Goro, despite the very different view from the crater floor.", "It goes into Major Healing Potions, and with Plaguebloom makes the Elixir of the Mongoose." } },
      [13466] = { name = "Plaguebloom", skill = 285, zones = { 1423, 1422 }, dungeons = {  }, note = { "Plaguebloom is gathered in the two Plaguelands, where finding useful growth amid the ruined fields is a small relief.", "Purification Potions and Mageblood Potions both use it; Mountain Silversage accompanies it in the Elixir of the Mongoose. Something gathered in that blighted country can still serve the living." } },
      [13467] = { name = "Icecap", skill = 290, zones = { 1452 }, dungeons = {  }, note = { "Icecap belongs to Winterspring's gathering routes. The snow gives an herbalist an unusually consistent landscape in which to learn its place.", "Major Mana Potions and Purification Potions use it, along with the Flask of Distilled Wisdom." } },
      [13468] = { name = "Black Lotus", skill = 300, zones = { 1428, 1452, 1423, 1451 }, dungeons = {  }, note = { "Black Lotus is a rare find in a small number of dangerous lands. A gatherer who spots it has good reason to remember the place.", "The great flasks call for it, including those of the Titans and Supreme Power. Many bundles can be replenished on an ordinary round; this one tends to determine when the most ambitious work can begin." } },
    },
    herbOrder = { 2447, 765, 2449, 785, 2452, 2450, 3820, 2453, 3355, 3369, 3356, 3357, 3818, 3821, 3358, 3819, 4625, 8831, 8153, 8836, 8838, 8839, 8845, 8846, 13464, 13463, 13465, 13466, 13467, 13468 },
    herbNodes = { [1619]=2449, [3726]=2449, [1618]=2447, [3724]=2447, [1617]=765, [3725]=765, [1620]=785, [3727]=785, [1621]=2450, [3729]=2450, [1622]=2453, [3730]=2453, [2045]=3820, [1623]=3355, [1628]=3369, [1624]=3356, [2041]=3357, [2042]=3818, [2046]=3821, [2043]=3358, [2044]=3819, [142140]=8153, [2866]=4625, [180165]=8831, [142141]=8836, [176642]=8836, [142142]=8838, [176636]=8838, [180164]=8838, [142143]=8839, [183046]=8839, [142144]=8845, [142145]=8846, [176637]=8846, [176583]=13464, [176638]=13464, [180167]=13464, [176584]=13463, [176639]=13463, [180168]=13463, [176586]=13465, [176640]=13465, [180166]=13465, [176587]=13466, [176641]=13466, [176588]=13467, [176589]=13468 },
    fish = {
      [6718] = { name = "Electropeller", kind = "quest", zones = { 1439 }, subzones = { "Cliffspring Falls", "Cliffspring River", "Grove of the Ancients", "Ruins of Mathystra", "Twilight Vale", "Wildbend River" }, dungeons = {  }, note = { "Electropellers are pieces of Wizbang Cranktoggle's machinery, lost in Darkshore's inland waters during an unsuccessful outing with an exploding duck decoy.", "He wants twelve recovered so that his research can continue. The duck decoy does rather more to explain the singed hair in his account than the fishing does." } },
      [6717] = { name = "Gaffer Jack", kind = "quest", zones = { 1439 }, subzones = {  }, dungeons = {  }, note = { "Gaffer jacks are lost tools, not fish: Wizbang Cranktoggle dropped a box of them overboard on his journey to Auberdine.", "He needs eight back to tune his stintle pegs. A line cast into the sea can supply the beginnings of another invention, though it was the inventor's drinking that supplied the tools to the sea." } },
      [16970] = { name = "Misty Reed Mahi Mahi", kind = "quest", zones = { 1435 }, subzones = { "Misty Reed Strand" }, dungeons = {  }, note = { "Misty Reed Mahi Mahi is sought off the Swamp of Sorrows, on the strand that gives it part of its name.", "Nat Pagle includes it among his four testing catches. Reaching the sea through that swamp gives the errand a difficult beginning, before the line is even cast." } },
      [16968] = { name = "Sar'theris Striker", kind = "quest", zones = { 1443 }, subzones = { "Sar'theris Strand" }, dungeons = {  }, note = { "The Sar'theris Striker takes Nat Pagle's pupil to the coast of Desolace.", "It is one of four catches in his test. The shore offers a change from the grey interior, though the journey remains a considerable one for a single fish." } },
      [16969] = { name = "Savage Coast Blue Sailfin", kind = "quest", zones = { 1434 }, subzones = { "Southern Savage Coast", "The Savage Coast" }, dungeons = {  }, note = { "Savage Coast Blue Sailfin is Nat Pagle's required catch from Stranglethorn.", "For a pupil who has already visited his other fishing grounds, the name marks another long journey. The lesson ranges far beyond the small patch of water where the teacher waits." } },
      [1467] = { name = "Spotted Sunfish", kind = "quest", zones = { 1433 }, subzones = {  }, dungeons = {  }, note = { "Spotted Sunfish is sought in Lake Everstill at Lakeshire.", "Dockmaster Baren buys a catch of ten. A line cast from the town's waters can bring in a little coin as well as a quiet interval beside the lake." } },
      [6291] = { name = "Raw Brilliant Smallfish", kind = "food", zones = { 1439, 1457, 1426, 1411, 1429, 1455, 1412, 1454, 1442, 1453, 1438, 1413, 1456, 1458, 1436 }, subzones = { "Blackthorn Ridge", "Blackwolf River", "Cliffspring Falls", "Cliffspring River", "Cragpool Lake", "Dreadmist Peak", "Grove of the Ancients", "Lushwater Oasis", "Ruins of Mathystra", "Sen'jin Village", "Southern Barrens", "Southfury River", "The Forgotten Pools", "The Sludge Fen", "The Stagnant Oasis", "Tor'kren Farm", "Twilight Vale", "Wildbend River" }, dungeons = { "The Deadmines", "Wailing Caverns" }, note = { "Brilliant Smallfish fills an apprentice's first creel in familiar waters, sometimes within sight of a city street.", "It makes a plain, useful meal. A modest catch is quite sufficient company for a quiet afternoon, especially when the cook is still learning too." } },
      [6303] = { name = "Raw Slitherskin Mackerel", kind = "food", zones = { 1439, 1411, 1421, 1438, 1413, 1420, 1436 }, subzones = { "Longshore", "North Tide's Run", "Rut'theran Village", "South Tide's Run", "The Great Sea", "The North Coast", "The Skittering Dark", "Westfall Lighthouse", "Whispering Shore" }, dungeons = {  }, note = { "Slitherskin Mackerel is a familiar early catch along the coast. It gives the sea angler a dependable beginning where the inland fisher has smallfish.", "The simple cooked dish keeps the same name." } },
      [12238] = { name = "Darkshore Grouper", kind = "food", zones = { 1439 }, subzones = { "Cliffspring Falls", "Cliffspring River", "Grove of the Ancients", "Ruins of Mathystra", "Twilight Vale", "Wildbend River" }, dungeons = {  }, note = { "Darkshore Grouper is sought in the rivers and falls inland from the coast.", "Gubber Blump at Auberdine asks for a catch of them and offers a fishing pole for the work. The fish can help equip an angler for whatever comes out of the next river." } },
      [6522] = { name = "Deviate Fish", kind = "special", zones = { 1413 }, subzones = { "Lushwater Oasis", "The Forgotten Pools", "The Stagnant Oasis" }, dungeons = { "Wailing Caverns" }, note = { "Deviate Fish inhabits the Barrens' oases and the Wailing Caverns below them, waters entangled with Naralex's troubled dream.", "Raw, its effects are unpredictable. Savory Deviate Delight can disguise the diner as a pirate or ninja, while alchemists use the fish in an Elixir of Giant Growth. This is a catch worth identifying before supper." } },
      [6358] = { name = "Oily Blackmouth", kind = "reagent", zones = { 1417, 1440, 1447, 1439, 1443, 1445, 1448, 1424, 1450, 1421, 1434, 1435, 1413, 1425, 1449, 1422, 1436, 1437 }, subzones = { "Alcaz Island", "Baradin Bay", "Bloodsail Compound", "Booty Bay", "Deepwater Tavern", "Dreadmurk Shore", "Dustwallow Bay", "Eastern Strand", "Ethel Rethor", "Faldir's Cove", "Grom'gol Base Camp", "Longshore", "Menethil Bay", "Menethil Harbor", "North Tide's Run", "Ranazjar Isle", "Ruins of Aboraz", "Shadowprey Village", "South Tide's Run", "Southshore", "Stagalbog", "The Cape of Stranglethorn", "The Crystal Shore", "The Drowned Reef", "The Forbidding Sea", "The Great Sea", "The Lost Fleet", "The Skittering Dark", "The Veiled Sea", "The Vile Reef", "The Zoram Strand", "Theramore Isle", "Tidefury Cove", "Western Strand", "Westfall Lighthouse", "Wild Shore", "Yojamba Isle", "Zuuldaia Ruins" }, dungeons = { "Maraudon" }, note = { "Oily Blackmouth gives an angler work for the alchemist as well as the cook. Its schools make a promising sight along the gathering coast.", "Blackmouth Oil goes into swimming draughts and the Elixir of Water Breathing. The catch can help another traveller spend a little longer in the water it came from." } },
      [6317] = { name = "Raw Loch Frenzy", kind = "food", zones = { 1432 }, subzones = {  }, dungeons = {  }, note = { "Loch Frenzy belongs to Loch Modan's great lake, with the Stonewrought Dam holding back the water above the Wetlands.", "Loch Frenzy Delight makes a local supper of a local catch. There are pleasant ways for a traveller to learn the name of a place." } },
      [6289] = { name = "Raw Longjaw Mud Snapper", kind = "food", zones = { 1440, 1439, 1457, 1426, 1411, 1431, 1429, 1424, 1455, 1412, 1454, 1433, 1421, 1442, 1453, 1438, 1413, 1456, 1420, 1458, 1436, 1437 }, subzones = { "Blackthorn Ridge", "Blackwolf River", "Cliffspring Falls", "Cliffspring River", "Cragpool Lake", "Dreadmist Peak", "Grove of the Ancients", "Lushwater Oasis", "Ruins of Mathystra", "Sen'jin Village", "Southern Barrens", "Southfury River", "The Forgotten Pools", "The Sludge Fen", "The Stagnant Oasis", "Tor'kren Farm", "Twilight Vale", "Wildbend River" }, dungeons = { "Blackfathom Deeps", "The Deadmines", "Wailing Caverns" }, note = { "Longjaw Mud Snapper is common in the home rivers and lakes, and follows anglers well beyond their first lessons.", "The ordinary catch is easily cooked. The occasional heavy specimen tends to acquire a different purpose: evidence in the evening's account of the fishing." } },
      [6361] = { name = "Raw Rainbow Fin Albacore", kind = "food", zones = { 1440, 1439, 1424, 1421, 1413, 1436, 1437 }, subzones = { "Baradin Bay", "Deepwater Tavern", "Eastern Strand", "Longshore", "Menethil Bay", "Menethil Harbor", "North Tide's Run", "South Tide's Run", "Southshore", "The Great Sea", "The Lost Fleet", "The Skittering Dark", "The Zoram Strand", "Western Strand", "Westfall Lighthouse" }, dungeons = {  }, note = { "Rainbow Fin Albacore comes from coastal water on both continents. It is one of the catches that makes an angler learn a shoreline as well as a road.", "Cooks prepare it under its own name." } },
      [6359] = { name = "Firefin Snapper", kind = "reagent", zones = { 1417, 1440, 1447, 1443, 1445, 1424, 1434, 1435, 1446, 1437 }, subzones = { "Alcaz Island", "Baradin Bay", "Bloodsail Compound", "Booty Bay", "Deepwater Tavern", "Dreadmurk Shore", "Dustwallow Bay", "Eastern Strand", "Ethel Rethor", "Faldir's Cove", "Grom'gol Base Camp", "Jagged Reef", "Menethil Bay", "Menethil Harbor", "Ranazjar Isle", "Ruins of Aboraz", "Shadowprey Village", "Southridge Beach", "Southshore", "Stagalbog", "Temple of Arkkoran", "The Cape of Stranglethorn", "The Crystal Shore", "The Drowned Reef", "The Forbidding Sea", "The Lost Fleet", "The Ruined Reaches", "The Shattered Strand", "The Veiled Sea", "The Vile Reef", "The Zoram Strand", "Theramore Isle", "Tidefury Cove", "Tower of Eldara", "Western Strand", "Wild Shore", "Yojamba Isle", "Zuuldaia Ruins" }, dungeons = {  }, note = { "Firefin Snapper is sought for oil rather than an evening meal. Its schools and the coast's oily fishing patches deserve an angler's attention.", "Fire Oil serves both Fire Protection Potions and the Elixir of Firepower. The alchemist decides whether the catch will help someone withstand the flame or wield it." } },
      [6308] = { name = "Raw Bristle Whisker Catfish", kind = "food", zones = { 1416, 1417, 1440, 1439, 1457, 1443, 1431, 1445, 1444, 1424, 1455, 1454, 1433, 1442, 1453, 1434, 1435, 1413, 1441, 1456, 1458, 1436, 1437 }, subzones = { "Blackthorn Ridge", "Blackwolf River", "Cliffspring Falls", "Cliffspring River", "Cragpool Lake", "Dreadmist Peak", "Grove of the Ancients", "Lushwater Oasis", "Ruins of Mathystra", "Southern Barrens", "Southfury River", "The Forgotten Pools", "The Sludge Fen", "The Stagnant Oasis", "Twilight Vale", "Wildbend River" }, dungeons = { "Scarlet Monastery", "The Deadmines", "Wailing Caverns" }, note = { "Bristle Whisker Catfish accompanies the freshwater angler across a wide stretch of country, including waters deep inside some very unwelcoming places.", "Most go toward supper. A large catfish weighed separately in pounds is likely to remain a subject of conversation much longer." } },
      [8365] = { name = "Raw Mithril Head Trout", kind = "food", zones = { 1416, 1417, 1447, 1443, 1445, 1448, 1444, 1450, 1434, 1435, 1425, 1441, 1449, 1422 }, subzones = {  }, dungeons = { "Maraudon", "Scarlet Monastery" }, note = { "Mithril Head Trout is a familiar catch in wilder inland waters, from the foothills to the lakes of Kalimdor.", "The cooked dish is Mithril Headed Trout. For all the metal in the name, its most dependable contribution to an expedition is another meal." } },
      [6362] = { name = "Raw Rockscale Cod", kind = "food", zones = { 1417, 1447, 1443, 1445, 1434, 1435, 1446 }, subzones = { "Alcaz Island", "Bloodsail Compound", "Booty Bay", "Dreadmurk Shore", "Dustwallow Bay", "Ethel Rethor", "Faldir's Cove", "Grom'gol Base Camp", "Jagged Reef", "Ranazjar Isle", "Ruins of Aboraz", "Shadowprey Village", "Southridge Beach", "Stagalbog", "Temple of Arkkoran", "The Cape of Stranglethorn", "The Crystal Shore", "The Drowned Reef", "The Forbidding Sea", "The Ruined Reaches", "The Shattered Strand", "The Veiled Sea", "The Vile Reef", "Theramore Isle", "Tidefury Cove", "Tower of Eldara", "Wild Shore", "Yojamba Isle", "Zuuldaia Ruins" }, dungeons = {  }, note = { "Rockscale Cod comes from coastal water farther along an angler's travels, with Stranglethorn and Tanaris among its fishing grounds.", "The cooked fish provides a straightforward supper." } },
      [16967] = { name = "Feralas Ahi", kind = "quest", zones = { 1444 }, subzones = { "Verdantis River" }, dungeons = {  }, note = { "The Feralas Ahi sends an angler to the Verdantis River, well away from Nat Pagle's own patch of Dustwallow.", "It is one of the four catches he asks for before passing on his finest teaching. A journey through Feralas is a substantial part of that lesson." } },
      [13757] = { name = "Lightning Eel", kind = "reagent", zones = { 1447, 1428, 1430, 1423, 1448, 1444, 1450, 1451, 1425, 1449, 1422, 1452 }, subzones = { "Jademir Lake" }, dungeons = { "Maraudon", "Scholomance", "Stratholme", "Zul'Gurub" }, note = { "Lightning Eel turns up in the wilder inland waters with catches such as Nightfin and Redgill.", "It has no familiar place among the cook's or alchemist's preparations. A field journal can still find room for a fish without first finding somebody a use for it." } },
      [13754] = { name = "Raw Glossy Mightfish", kind = "food", zones = { 1447, 1446 }, subzones = { "Jagged Reef", "Southridge Beach", "Temple of Arkkoran", "The Ruined Reaches", "The Shattered Strand", "Tower of Eldara" }, dungeons = {  }, note = { "Glossy Mightfish is caught off Tanaris and Azshara, in waters that reward an experienced angler.", "Cooked Glossy Mightfish restores health and adds stamina. A smaller fish can supply much the same encouragement before a battle as the larger catch prepared for steaks." } },
      [13759] = { name = "Raw Nightfin Snapper", kind = "food", zones = { 1447, 1428, 1423, 1448, 1444, 1450, 1451, 1425, 1449, 1422, 1452 }, subzones = { "Jademir Lake" }, dungeons = { "Maraudon", "Scholomance", "Stratholme", "Zul'Gurub" }, note = { "Nightfin Snapper makes the hour part of choosing a fishing place. It bites at night and around the day's edges, with the small hours particularly favourable.", "Nightfin Soup helps restore a spellcaster's mana. A patient angler can give the company a useful reason to be grateful for time spent beside dark water." } },
      [13758] = { name = "Raw Redgill", kind = "food", zones = { 1447, 1428, 1423, 1448, 1444, 1450, 1451, 1425, 1449, 1422, 1452 }, subzones = { "Jademir Lake" }, dungeons = { "Maraudon", "Scholomance", "Stratholme", "Zul'Gurub" }, note = { "Redgill keeps the freshwater angler company by day or night, in many of the waters where the hour determines other catches.", "Filet of Redgill provides a dependable meal. Heavy specimens are weighed separately, and tend to receive rather more attention before anyone fetches the knife." } },
      [4603] = { name = "Raw Spotted Yellowtail", kind = "food", zones = { 1417, 1447, 1443, 1445, 1434, 1435, 1446 }, subzones = { "Alcaz Island", "Bay of Storms", "Bloodsail Compound", "Booty Bay", "Dreadmurk Shore", "Dustwallow Bay", "Ethel Rethor", "Faldir's Cove", "Grom'gol Base Camp", "Hetaera's Clutch", "Jagged Reef", "Ranazjar Isle", "Ruins of Aboraz", "Scalebeard's Cave", "Shadowprey Village", "Southridge Beach", "Stagalbog", "Temple of Arkkoran", "The Cape of Stranglethorn", "The Crystal Shore", "The Drowned Reef", "The Forbidding Sea", "The Ruined Reaches", "The Shattered Strand", "The Veiled Sea", "The Vile Reef", "Theramore Isle", "Tidefury Cove", "Tower of Eldara", "Wild Shore", "Yojamba Isle", "Zuuldaia Ruins" }, dungeons = {  }, note = { "Spotted Yellowtail shares much of the coastal fishing ground of Rockscale Cod.", "It has its own place in the cook's repertoire, even when both arrive in the same creel. The sea need not provide a rare catch to provide some variety." } },
      [13756] = { name = "Raw Summer Bass", kind = "food", zones = { 1447, 1444, 1434, 1446, 1425 }, subzones = { "Bay of Storms", "Feathermoon Stronghold", "Hetaera's Clutch", "Isle of Dread", "Jagged Reef", "Jaguero Isle", "Revantusk Village", "Ruins of Solarsal", "Sardor Isle", "Scalebeard's Cave", "Southridge Beach", "Temple of Arkkoran", "The Forgotten Coast", "The Overlook Cliffs", "The Ruined Reaches", "The Shattered Strand", "Tower of Eldara" }, dungeons = {  }, season = "summer", note = { "Summer Bass is a seasonal catch of the southern coasts. An angler revisiting a winter fishing place may find a different supper waiting.", "Hot Smoked Bass gives it a place at the fire. The changing season can reach the cooking pot even when the expedition has stayed in the same camp." } },
      [13760] = { name = "Raw Sunscale Salmon", kind = "food", zones = { 1447, 1428, 1423, 1448, 1444, 1450, 1451, 1425, 1449, 1422, 1452 }, subzones = { "Jademir Lake" }, dungeons = { "Maraudon", "Scholomance", "Stratholme", "Zul'Gurub" }, note = { "Sunscale Salmon favours daylight in waters also known for Nightfin Snapper. An afternoon that disappoints the night angler may suit this catch very well.", "Poached Sunscale Salmon helps health return steadily. The two catches put the same stretch of water to work for different appetites at different hours." } },
      [13422] = { name = "Stonescale Eel", kind = "reagent", zones = { 1447, 1446 }, subzones = { "Bay of Storms", "Hetaera's Clutch", "Jagged Reef", "Scalebeard's Cave", "Southridge Beach", "Temple of Arkkoran", "The Ruined Reaches", "The Shattered Strand", "Tower of Eldara" }, dungeons = {  }, note = { "Stonescale Eels are a valuable catch off Azshara and Tanaris, especially where a swarm gathers.", "Stonescale Oil goes into Greater Stoneshield Potions and powerful flasks. A quiet spell of fishing can end in supplies intended for a very noisy fight." } },
      [13755] = { name = "Winter Squid", kind = "food", zones = { 1447, 1444, 1434, 1446, 1425 }, subzones = { "Bay of Storms", "Feathermoon Stronghold", "Hetaera's Clutch", "Isle of Dread", "Jaguero Isle", "Revantusk Village", "Ruins of Solarsal", "Sardor Isle", "Scalebeard's Cave", "The Forgotten Coast", "The Overlook Cliffs" }, dungeons = {  }, season = "winter", note = { "Winter Squid replaces Summer Bass in the seasonal coastal catch. A familiar fishing place is worth returning to when the year turns.", "Grilled Squid sharpens agility. The cooks who value it have a practical interest in keeping track of the season, quite apart from the weather." } },
      [13888] = { name = "Darkclaw Lobster", kind = "food", zones = { 1447 }, subzones = { "Bay of Storms", "Hetaera's Clutch", "Scalebeard's Cave" }, dungeons = {  }, note = { "Azshara's Bay of Storms is the fishing ground for Darkclaw Lobster. The name of the water gives a fair impression of the country around an angler's chosen shore.", "Lobster Stew repays the journey with a substantial meal. The separately weighed lobsters give the same water another claim on a fisher's memory." } },
      [13893] = { name = "Large Raw Mightfish", kind = "food", zones = { 1447 }, subzones = { "Bay of Storms", "Hetaera's Clutch", "Scalebeard's Cave" }, dungeons = {  }, note = { "Large Mightfish comes from the Bay of Storms, where experienced anglers also seek Darkclaw Lobster.", "Mightfish Steak gives a hearty meal with added stamina. The separately weighed giants of the same waters are a different prize, one that can make a fisher's account sound implausible even when it is exact." } },
      [13890] = { name = "Plated Armorfish", kind = "reagent", zones = { 1428, 1423, 1444, 1451, 1452 }, subzones = { "Jademir Lake" }, dungeons = { "Scholomance", "Stratholme", "Zul'Gurub" }, note = { "Plated Armorfish is a less familiar prize from waters that also yield Whitescale Salmon.", "The cook has no usual preparation for it. Its place in the catch is worth recording all the same; a creel contains more than the ingredients on a shopping list." } },
      [13889] = { name = "Raw Whitescale Salmon", kind = "food", zones = { 1428, 1423, 1444, 1451, 1452 }, subzones = { "Jademir Lake" }, dungeons = { "Scholomance", "Stratholme", "Zul'Gurub" }, note = { "Whitescale Salmon is caught in difficult waters, including Winterspring and the lands around the plague's great strongholds.", "Baked Salmon makes a fine meal from the ordinary catch; the heavier specimens are weighed separately." } },
      [6309] = { name = "Catfish", kind = "record", zones = { 1416, 1417, 1440, 1439, 1457, 1443, 1431, 1445, 1444, 1424, 1455, 1454, 1433, 1442, 1453, 1434, 1435, 1413, 1441, 1456, 1458, 1436, 1437 }, subzones = { "Blackthorn Ridge", "Blackwolf River", "Cliffspring Falls", "Cliffspring River", "Cragpool Lake", "Dreadmist Peak", "Grove of the Ancients", "Lushwater Oasis", "Ruins of Mathystra", "Southern Barrens", "Southfury River", "The Forgotten Pools", "The Sludge Fen", "The Stagnant Oasis", "Twilight Vale", "Wildbend River" }, dungeons = { "Scarlet Monastery", "The Deadmines", "Wailing Caverns" }, note = { "The large catfish are weighed individually, from seventeen pounds up to the uncommon thirty-two-pound catch.", "They share the Bristle Whisker Catfish's waters. An ordinary fishing place can supply an extraordinary addition to an evening's story." } },
      [13876] = { name = "Grouper", kind = "record", zones = { 1447, 1446 }, subzones = { "Jagged Reef", "Southridge Beach", "Temple of Arkkoran", "The Ruined Reaches", "The Shattered Strand", "Tower of Eldara" }, dungeons = {  }, note = { "These groupers weigh from forty to sixty-eight pounds and come from the coasts of Tanaris and Azshara.", "For once, the weight alone does much of the work of describing a catch. The angler's part in the account is getting it out of the sea." } },
      [13907] = { name = "Lobster", kind = "record", zones = { 1447 }, subzones = { "Bay of Storms", "Hetaera's Clutch", "Scalebeard's Cave" }, dungeons = {  }, note = { "Weighed lobsters of seven to twenty-two pounds come from Azshara's Bay of Storms.", "A catch at the upper end of that range deserves a careful entry in the journal. \"A lobster\" is a rather modest description of what has come out of the water." } },
      [13914] = { name = "Mightfish", kind = "record", zones = { 1447 }, subzones = { "Bay of Storms", "Hetaera's Clutch", "Scalebeard's Cave" }, dungeons = {  }, note = { "The greatest weighed mightfish run from seventy to a hundred and three pounds, in Azshara's Bay of Storms.", "Even without an angler's additions, a catch approaching a hundred pounds is quite sufficient explanation for coming home late." } },
      [6292] = { name = "Mud Snapper", kind = "record", zones = { 1426, 1411, 1429, 1412, 1438 }, subzones = { "Sen'jin Village", "Southfury River", "Tor'kren Farm" }, dungeons = {  }, note = { "Mud snappers of ten, twelve and fifteen pounds are caught alongside the Longjaw Mud Snapper.", "The familiar home waters still have room for a surprise. A fisher need not reach a distant coast to bring back something worth weighing." } },
      [13885] = { name = "Redgill", kind = "record", zones = { 1447, 1448, 1450, 1425, 1449, 1422 }, subzones = {  }, dungeons = { "Maraudon" }, note = { "Heavy redgill run from thirty-four to fifty-two pounds, in the same high-country waters as the ordinary catch.", "The notebook becomes particularly useful here. A precise weight is a small defence against the reasonable suspicion that the story has grown on the way home." } },
      [13901] = { name = "Salmon", kind = "record", zones = { 1428, 1423, 1444, 1451, 1452 }, subzones = { "Jademir Lake" }, dungeons = { "Scholomance", "Stratholme", "Zul'Gurub" }, note = { "The separately weighed salmon run from fifteen to twenty-nine pounds and accompany Whitescale Salmon in the catch.", "They give a familiar fishing expedition an individual result: this fish, at this weight, from this stretch of water." } },
    },
