        { id = "mulgore-ravaged-caravan", tier = "near", asks = "gesture", danger = "Quiet", circle = { 53, 46, 8 }, verse = { "On the north shore of the bull's lake, a caravan burned:", "its guards beaten, its crates left to the torches.", "The torches were careless. What the crates still hold", "tells what the goblins meant to take from the land." }, hint = "North of Bloodhoof Village, on the shore of Stonebull Lake; the crates are worth going through.", name = "+,rbU-~EEf&i~4l", note = "-3a!@)1'ijw(K4p'3#VX|PV;%AP#i<D?*k`<E'a9#x'$Fn-6>y@<&'i#)SHLVdU@cxvygUH[9pqPw`KM'd", margin = "-3a!==/8ws\"mzF},\".TJlua1y]@'X8F3-&s2+,x<di2/Hq\"FLq;S0m32#D<LpT*?Ub80ZZYYz?tCs_a@yKp5KP$l|,-x2Y+5!+%iJ*:>A4&fV2Y8Db`T)7E8m@s= Y)2s;`W3z@^2rr)\"'(|iT &<7JK", area = true, at = { 639848030 }, by = { 825685780, 1271284607 } },
